INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4050', 'spa', 'Abundancia, excedente, desbordamiento; una medida que sobrepasa lo ordinario o esperado.', 'Sustantivo derivado de περισσεύω (abundar), que denota excedente o cantidad desbordante. Pablo lo utiliza para hablar de la abundancia de gracia que supera con creces al pecado (Ro 5:17) y del gozo desbordante de los macedonios en medio de pruebas severas (2 Co 8:2). En Santiago 1:21 describe el «exceso de maldad» del que los creyentes deben despojarse. La idea central es la de algo que se derrama más allá de lo ordinario o esperado, ya sea en sentido positivo (gracia, gozo, generosidad) o negativo (maldad). Equivale al concepto de sobreabundancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4051', 'spa', 'Abundancia, excedente, desbordamiento; lo que sobra o rebosa, sea de palabras del corazón o de provisiones materiales.', 'Sustantivo que designa lo que sobra, rebosa o excede lo necesario. Jesús lo emplea de forma memorable en Mat 12:34 y Luc 6:45: «de la abundancia del corazón habla la boca», donde la metáfora del desbordamiento vincula el carácter interior con la expresión exterior. En Mar 8:8 se usa concretamente para los fragmentos sobrantes tras el milagro de la multiplicación. Pablo lo aplica en 2 Cor 8:14 al excedente material que puede suplir la carencia ajena. El término abarca tanto la plenitud abstracta como el sobrante concreto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4052', 'spa', 'Abundar, rebosar, tener en exceso; sobrar como sobrante; causativamente, hacer abundar o prodigar', 'Abundar, rebosar, tener en exceso; sobrar como sobrante; causativamente, hacer abundar o prodigar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4053', 'spa', 'Excesivo, abundante, más que; grado comparativo de excedente, grado extraordinario, o lo que es superfluo o ventajoso.', 'Excesivo, abundante, más que; grado comparativo de excedente, grado extraordinario, o lo que es superfluo o ventajoso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4054', 'spa', 'fuera de lo común, extraordinario, excesivo; extraño, llamativo (περισσός/περιττός)', 'Este adjetivo (derivado de περί) describe lo que excede los límites normales: dones prodigiosos, conocimiento extraordinario, estilo literario llamativo. Puede significar ''fuera de lo común'', ''extraño'' o ''excepcional''. Aristóteles lo emplea para describir al perro como el animal más sociable de todos. En el Nuevo Testamento se pregunta: ''¿Qué hacéis de extraordinario?'' En literatura, τὸ περιττόν designa una cualidad ornamentada y llamativa. La palabra abarca tanto la excelencia positiva como la rareza negativa, unidas por el hecho de sobrepasar lo ordinario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4055', 'spa', 'más extraordinario, más excesivo (comparativo de περισσός); usos adverbiales', 'Forma comparativa de περισσός, que significa ''más extraordinario'' o ''más excesivo''. Puede funcionar como adjetivo, describiendo algo como más excepcional, o como adverbio, con el sentido de ''más abundantemente'' o ''con mayor exceso''. Su rango semántico sigue al del grado positivo: sobrepasar los límites normales en cantidad, calidad o singularidad. La palabra enfatiza el hecho de superar aquello que ya de por sí está más allá de lo ordinario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4056', 'spa', 'más abundantemente, con mayor exceso (forma adverbial comparativa de περισσός)', 'Esta forma adverbial del comparativo περισσότερος intensifica la manera o el grado de una acción: hacer algo «más abundantemente» o «con mayor exceso». En el griego del Nuevo Testamento funciona para enfatizar la sobreabundancia, el desbordamiento o una medida excepcional. La palabra se construye sobre el sentido raíz de περί (alrededor, más allá) para expresar que se sobrepasan los límites normales de manera aún mayor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4057', 'spa', 'Este adverbio intensifica acciones o estados más allá de la medida normal, expresando ''sobremanera'', ''mucho más'' o ''con mayor abundancia''. Con frecuen', 'Este adverbio intensifica acciones o estados más allá de la medida normal, expresando ''sobremanera'', ''mucho más'' o ''con mayor abundancia''. Con frecuencia marca una escalada: la multitud grita con mayor insistencia pidiendo la crucifixión (Mt 27:23; Mr 15:14), los discípulos se asombran sobremanera ante la enseñanza de Jesús sobre las riquezas (Mr 10:26) y Pedro insiste aún con más vehemencia en que no negará al Señor (Mr 14:31).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4058', 'spa', 'Paloma — la paloma o pichón común, tanto como ave sacrificial como símbolo del descenso del Espíritu Santo. El sustantivo περιστερά (peristera) se ref', 'Paloma — la paloma o pichón común, tanto como ave sacrificial como símbolo del descenso del Espíritu Santo. El sustantivo περιστερά (peristera) se refiere a la paloma o pichón (Columba livia y especies afines), y aparece en contextos neotestamentarios tanto literales como figurados. En sentido literal, las palomas se vendían en los atrios del templo para sacrificio, y Jesús volcó las mesas de los vendedores de palomas durante la purificación del templo (Mt 21:12; Mc 11:15; Jn 2:14-16). En sentido figurado, el Espíritu Santo descendió «como paloma» sobre Jesús en su bautismo, imagen atestiguada en los cuatro Evangelios (Mt 3:16; Mc 1:10; Lc 3:22; Jn 1:32). Jesús también instruye a sus discípulos a ser «sencillos como palomas» (Mt 10:16), combinando astucia con inocencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4059', 'spa', 'Περιτέμνω se encuentra en el centro de uno de los debates más trascendentales del Nuevo Testamento: ¿deben los creyentes gentiles someterse a la circu', 'Περιτέμνω se encuentra en el centro de uno de los debates más trascendentales del Nuevo Testamento: ¿deben los creyentes gentiles someterse a la circuncisión para ser salvos? El verbo aparece tanto en voz activa (realizar el rito) como en voz pasiva/media (someterse a él), y la distinción tiene importancia teológica. En su sentido activo, describe a Abraham circuncidando a Isaac al octavo día (Hch 7:8), la circuncisión acostumbrada de Jesús (Lc 2:21) y la ley de Moisés que ordena la práctica (Jn 7:22). En la voz pasiva, se convierte en el punto candente del Concilio de Jerusalén (Hch 15:1, 5, 24) y del argumento de Pablo de que la circuncisión no aprovecha nada si no se cumple la ley (Gá 5:2-3; 6:12-13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4060', 'spa', 'Poner alrededor, colocar encima o sobre; usado para vestir a alguien, cercar algo, o metafóricamente conferir honor o deshonra.', 'Περιτίθημι combina περί (alrededor) y τίθημι (poner): colocar algo alrededor o sobre alguien. El NT lo emplea en escenas marcadamente concretas de la Pasión: el manto púrpura puesto sobre Jesús en burla (Mt 27:28, Mr 15:17, Jn 19:2) y la esponja empapada en vinagre colocada en una caña y acercada a su boca (Mt 27:48, Mr 15:36). En las parábolas, describe a un dueño que cerca su viña con un vallado (Mt 21:33, Mr 12:1). Pablo luego lleva el verbo al terreno metafórico en 1 Corintios 12:23, donde los miembros considerados «menos dignos» son revestidos de mayor honor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4061', 'spa', 'Circuncisión; el rito de alianza de cortar el prepucio, y por metonimia el pueblo judío', 'Circuncisión; el rito de alianza de cortar el prepucio, y por metonimia el pueblo judío');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4062', 'spa', 'trastornar, enloquecer; dar vuelta o perturbar', 'Verbo que significa hacer girar, trastornar o llevar a la locura. En Hechos 26:24, Festo acusa a Pablo: ''Las muchas letras te están volviendo loco'' (εἰς μανίαν περιτρέπει). El término puede significar perturbar, trastornar o llevar a alguien a la demencia. Festo interpreta el apasionado testimonio de Pablo sobre la resurrección como evidencia de locura causada por el exceso de estudio. El verbo capta la percepción del gobernador de que el mensaje de Pablo desestabilizaba la razón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4063', 'spa', 'correr por todas partes, recorrer apresuradamente una zona en todas direcciones', 'Este verbo significa correr por todas partes o recorrer apresuradamente un área en diversas direcciones. En Marcos 6:55, la gente ''recorrió'' (περιέδραμον) toda aquella región, trayendo a los enfermos en camillas a donde oían que Jesús estaba. El término transmite un movimiento rápido y generalizado a lo largo de un territorio. Subraya la urgencia y el entusiasmo con que las personas buscaban el poder sanador de Jesús, movilizándose con fervor y esperanza ante la noticia de su presencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4064', 'spa', 'Llevar de un lado a otro, transportar; cargar algo consigo constantemente o moverlo de lugar en lugar', 'Este verbo significa llevar algo consigo, transportandolo de un lugar a otro. La gente traia a los enfermos en camillas, «llevandolos de un lado a otro» adonde oian que Jesus estaba (Mr 6:55). Pablo habla de «llevar siempre» en el cuerpo la muerte de Jesus (2 Co 4:10). Tambien advierte contra ser «llevados por doquier» por cualquier viento de doctrina (Ef 4:14). Ya sea transportando enfermos fisicamente, sobrellevando los sufrimientos de Cristo o siendo arrastrado por falsas ensenanzas, la palabra enfatiza movimiento constante y acompanamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4065', 'spa', 'despreciar, menospreciar, tratar con desdén o desestima', 'Este verbo significa despreciar, menospreciar o tratar con desdén. Pablo lo emplea en Tito 2:15 para exhortar a Tito: ''Que nadie te menosprecie'' (μηδείς σου περιφρονείτω). El término transmite la idea de mirar por encima del hombro a alguien o considerarlo indigno de respeto. La instrucción de Pablo anima a Tito a enseñar con autoridad para que ni su juventud ni su posición fueran motivo de desprecio. En el uso clásico incluía el sentido de reflexionar sobre algo, pero predominó el significado de despreciar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4066', 'spa', 'La región circundante o comarca; el área en torno a un lugar determinado.', 'Adjetivo sustantivado que significa «la región de alrededor», referido típicamente a la comarca o territorio que rodea una ciudad o un punto geográfico notable. Cuando Mateo relata que «toda la región alrededor del Jordán» salió al encuentro de Juan (Mt 3:5), o que la fama de Jesús se extendió por «toda la comarca» de Galilea (Mr 1:28), el término traza una zona geográfica definida por su centro. En los Evangelios designa de forma constante el área circundante de una ciudad, río o territorio: la región del Jordán (Mt 3:5, Lc 3:3), la tierra de Genesaret (Mt 14:35) o el campo galileo en general (Mr 1:28, Lc 4:14, 4:37).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4067', 'spa', 'desecho, basura, escoria de la sociedad; lo más despreciable y descartado', 'Sustantivo que significa desecho, basura o escoria: aquello que carece de valor y se desecha por inservible. Pablo lo utiliza en 1 Corintios 4:13 junto con ''inmundicia'' (περικάθαρμα) para describir cómo el mundo percibe a los apóstoles: como ''el desecho de todas las cosas.'' El término denota el estatus más bajo y despreciado posible. Pablo abraza esta degradación para mostrar el contraste radical entre los valores mundanos y las realidades del reino de Dios, donde la debilidad y la humildad son honradas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4068', 'spa', 'jactarse, presumir, actuar con arrogancia ostentosa', 'Este verbo significa jactarse, presumir o actuar con orgullo arrogante. Pablo lo emplea en 1 Corintios 13:4 para describir lo que el amor no hace: ''el amor no se jacta'' (οὐ περπερεύεται). El término capta la autoexaltación presuntuosa y la exhibición vanidosa. En el contexto del carácter del amor, Pablo contrasta el amor humilde con la autoexaltación orgullosa. El amor verdadero no se pavonea ni busca impresionar a los demás con su propia importancia, sino que se entrega con humildad al servicio del prójimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4069', 'spa', 'Pérsida; mujer cristiana saludada por Pablo en Romanos 16:12', 'Nombre propio femenino que significa ''mujer persa,'' perteneciente a una creyente cristiana en Roma a quien Pablo saluda con afecto. En Romanos 16:12, Pablo la llama ''la amada Pérsida, la cual ha trabajado mucho en el Señor.'' El nombre sugiere un origen o herencia étnica persa. La recomendación de Pablo destaca su labor en el ministerio, usando el mismo verbo (κοπιάω) que aplica a otros obreros fieles. Pérsida ejemplifica el servicio dedicado y el papel significativo de las mujeres en la iglesia primitiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4071', 'spa', 'Ave, pájaro — criaturas aladas del cielo, usado colectivamente para las aves silvestres en la naturaleza y en imágenes parabólicas. Derivado del adjet', 'Ave, pájaro — criaturas aladas del cielo, usado colectivamente para las aves silvestres en la naturaleza y en imágenes parabólicas. Derivado del adjetivo πετεινός (''capaz de volar, alado''), este sustantivo designa a las aves de manera colectiva, en particular las aves silvestres del cielo abierto. En los Evangelios aparece de forma destacada en la enseñanza de Jesús: las aves del cielo no siembran ni siegan, y sin embargo el Padre celestial las alimenta (Mt 6:26), y las aves vienen a anidar en las ramas del árbol de mostaza (Mt 13:32). La parábola del sembrador emplea a las aves como agentes que devoran la semilla caída en el camino (Mt 13:4; Mr 4:4). Las 14 ocurrencias neotestamentarias presentan un perfil monosémico uniforme.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4072', 'spa', 'Volar; dicho de aves y criaturas aladas que surcan el cielo, usado exclusivamente en las visiones apocalípticas.', 'Verbo que significa volar, limitado en el NT exclusivamente al libro de Apocalipsis, donde aparece en vívidas escenas apocalípticas. El cuarto ser viviente junto al trono se asemeja a un águila volando (Ap 4:7). Un águila vuela por el cenit proclamando tres ayes sobre la tierra (8:13). A la mujer se le dan alas de águila para volar al desierto (12:14). Un ángel vuela por en medio del cielo anunciando el evangelio eterno (14:6), y otro convoca a las aves que vuelan por el cenit al gran banquete (19:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4073', 'spa', 'Roca, peña, acantilado; una gran masa sólida de piedra, usada literalmente y como metáfora de fundamento firme. Se refiere a una gran masa inamovible ', 'Roca, peña, acantilado; una gran masa sólida de piedra, usada literalmente y como metáfora de fundamento firme. Se refiere a una gran masa inamovible de piedra —roca madre, pared de acantilado o afloramiento rocoso— distinta de λίθος, que típicamente designa una piedra suelta o un bloque de construcción. La palabra tiene un peso teológico enorme en uno de los pasajes más discutidos del Nuevo Testamento: ''sobre esta πέτρα edificaré mi iglesia'' (Mt 16:18). También aparece en contextos prácticos y apocalípticos: el constructor sabio edifica sobre la roca (Mt 7:24-25), el sepulcro de José de Arimatea está labrado en la roca viva (Mt 27:60), las rocas se parten en la crucifixión (Mt 27:51), y la humanidad aterrorizada suplica a las rocas que caigan sobre ellos (Ap 6:15-16). Pablo identifica la roca que seguía a Israel en el desierto como Cristo (1 Co 10:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4074', 'spa', 'Pedro; Simón Pedro, el apóstol principal, llamado ''Roca'' por Jesús', 'Πέτρος significa ''piedra'' o ''roca'' en griego, pero en el Nuevo Testamento funciona casi exclusivamente como nombre propio de Simón Pedro, el pescador de Betsaida a quien Jesús llamó primero entre los Doce. El nombre es traducción del arameo Kefá (Cefas), otorgado por Jesús en la declaración de Mateo 16:18: ''Tú eres Pedro, y sobre esta roca edificaré mi iglesia''. Con 156 apariciones, el nombre de Pedro figura en todos los Evangelios, a lo largo de Hechos y en referencias epistolares, lo que lo convierte en el discípulo más frecuentemente nombrado del Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4075', 'spa', 'Pedregoso, rocoso; describe terreno poco profundo con una fina capa de tierra sobre roca madre.', 'Adjetivo que significa «rocoso» o «pedregoso». πετρῶδες aparece exclusivamente en la parábola del sembrador y su explicación (Mat 13:5, 20; Mar 4:5, 16). Describe un terreno donde una delgada capa de tierra descansa sobre roca madre: la semilla brota rápido pero carece de profundidad para echar raíces y se marchita con el sol. No se trata de suelo esparcido con piedras sueltas, sino de tierra superficial sobre lecho rocoso, una distinción agrícola fundamental que simboliza a quienes reciben la palabra con gozo pero caen ante la presión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4076', 'spa', 'ruda; hierba aromática (Ruta graveolens) usada como condimento y en medicina', 'Sustantivo que designa la ruda, una hierba de aroma intenso empleada en la cocina y la medicina. Jesús la menciona en Lucas 11:42, donde reprende a los fariseos por diezmar escrupulosamente «la ruda y toda hortaliza» mientras descuidan la justicia y el amor de Dios. La ruda se cultivaba en huertos y estaba sujeta al diezmo según la interpretación farisaica. El punto de Jesús no es condenar la observancia meticulosa, sino censurar a quienes se obsesionan con lo menor y pasan por alto lo verdaderamente importante: la misericordia, la justicia y el amor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4077', 'spa', 'Manantial, fuente, origen — una fuente natural de agua; en sentido figurado, el origen de la vida, la bendición o la contaminación. El sustantivo πηγή', 'Manantial, fuente, origen — una fuente natural de agua; en sentido figurado, el origen de la vida, la bendición o la contaminación. El sustantivo πηγή (pege) designa un manantial, fuente o surgencia de agua. Su aparición teológicamente más rica se halla en la conversación de Jesús con la mujer samaritana, donde contrasta el pozo de Jacob con el ''manantial de agua que brota para vida eterna'' que él ofrece (Juan 4:6, 14). Marcos lo emplea para la ''fuente de sangre'' de la mujer con hemorragia, que se secó al toque de Jesús (Marcos 5:29). Santiago pregunta si un manantial puede echar agua dulce y salobre por la misma abertura (Santiago 3:11-12), convirtiéndolo en metáfora de la inconsistencia de la lengua. En Apocalipsis, los manantiales son objeto tanto de juicio (Apocalipsis 8:10; 14:7; 16:4) como de promesa escatológica: el Cordero guiará a su pueblo a ''fuentes de aguas vivas'' (Apocalipsis 7:17; 21:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4078', 'spa', 'plantar, erigir (una tienda o tabernáculo); establecer firmemente', 'Verbo que significa fijar, afirmar o levantar, especialmente una tienda o tabernáculo. En Hebreos 8:2, el autor describe el verdadero tabernáculo «que levantó el Señor» (ἔπηξεν), no el hombre. El término subraya la acción de establecer o erigir con firmeza. Aquí se contrasta el tabernáculo terrenal, hecho por manos humanas, con el santuario celestial establecido por Dios. El verbo enfatiza la iniciativa divina y la permanencia de lo que Dios edifica frente a lo transitorio de la obra humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4081', 'spa', 'Lodo, barro; tierra blanda y húmeda que puede moldearse o aplicarse, usada exclusivamente en Juan 9 para la sanidad del ciego.', 'Πηλός designa el lodo o barro, tierra blanda y húmeda que puede moldearse o untarse. Aunque en el griego clásico tenía usos amplios (arcilla de alfarero, mortero, incluso sedimento turbio del vino), cada aparición en el Nuevo Testamento pertenece a una sola narración vívida: Jesús prepara barro con saliva y tierra, lo unta en los ojos de un ciego y lo envía a lavarse en el estanque de Siloé (Juan 9:6-15). Las traducciones en español resultan reveladoras: «lodo» apunta a la tierra informe y «barro» a la materia moldeable, reflejando la doble naturaleza de la sustancia como tierra cruda y algo deliberadamente formado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4082', 'spa', 'Alforja o bolsa de viajero; morral de cuero para llevar provisiones en un viaje.', 'Πήρα designa una bolsa o alforja de cuero utilizada por los viajeros para transportar alimentos y suministros básicos. En todas las apariciones del Nuevo Testamento, Jesús ordena a sus discípulos salir sin ella, un mandato llamativo que exige depender por completo de la hospitalidad de aquellos a quienes sirven. Mateo 10:10 y Lucas 10:4 registran esta instrucción para la misión de los Doce y de los Setenta y dos; Marcos 6:8 permite un bastón pero prohíbe la bolsa. Lucas 22:35-36 retoma la instrucción cuando Jesús pregunta: «Cuando os envié sin bolsa ni alforja, ¿os faltó algo?» El alemán «Reisetasche» (bolsa de viaje) capta con precisión su función.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4083', 'spa', 'Codo, unidad antigua de medida (~45 cm); la distancia del codo al extremo de los dedos.', 'Originalmente designaba el antebrazo desde el codo hasta la punta de los dedos, y se convirtió en la unidad estándar de medida lineal en la antigüedad, equivalente a unos 45 centímetros. Jesús lo usa en sentido figurado al preguntar quién puede añadir un solo codo a su estatura o a la duración de su vida (Mat 6:27; Luc 12:25), exponiendo la inutilidad de la ansiedad. En Juan 21:8 mide la distancia literal desde la orilla, y en Apocalipsis 21:17 especifica el grosor del muro de la Nueva Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4084', 'spa', 'Prender o aprehender a una persona por la fuerza; también pescar o atrapar animales. En el Nuevo Testamento este verbo casi siempre conlleva la fuerza', 'Prender o aprehender a una persona por la fuerza; también pescar o atrapar animales. En el Nuevo Testamento este verbo casi siempre conlleva la fuerza de apresar o arrestar a alguien, apareciendo de forma prominente en el Evangelio de Juan donde las autoridades intentan repetidamente echar mano a Jesús (Jn 7:30, 32, 44; 8:20; 10:39). En su sentido secundario, la palabra retorna a su significado más antiguo y concreto de pescar, como cuando los discípulos sacan su captura en el mar de Tiberíades (Jn 21:3, 10). Ambos sentidos comparten la idea central de agarrar algo que se resiste o escapa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4085', 'spa', 'apretar, comprimir; prensar firmemente para compactar', 'Verbo que significa apretar, comprimir o prensar. Jesús lo utiliza en Lucas 6:38 dentro de la imagen de la generosidad desbordante: «medida buena, apretada, remecida y rebosando». El término describe la acción de compactar grano o mercancías para maximizar la cantidad en un recipiente. Ilustra la generosidad abundante y desbordante con la que Dios responde a quienes dan con desprendimiento. La bendición divina excede toda medida humana, devolviendo con creces lo que se ha entregado con corazón abierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4086', 'spa', 'discurso persuasivo; retórica plausible pero potencialmente engañosa', 'Sustantivo que designa un discurso persuasivo o un argumento de apariencia convincente, a menudo con matiz de engaño. Pablo lo emplea en Colosenses 2:4 para advertir: «que nadie os engañe con discursos persuasivos» (πιθανολογίᾳ). El término enfatiza una retórica que suena convincente pero puede carecer de sustancia o verdad. Pablo contrasta esa elocuencia humana con la solidez del evangelio, advirtiendo contra el peligro de dejarse seducir por una filosofía ingeniosa pero vacía que aparta de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4087', 'spa', 'Amargar; hacer amargo o causar amargura, tanto en sentido literal (sabor) como figurado (emoción).', 'Derivado del adjetivo πικρός (amargo), este verbo significa hacer algo amargo o volverse amargado. En Apocalipsis describe aguas convertidas en amargas por la estrella Ajenjo (8:11) y el rollo agridulce que endulza la boca pero amarga el estómago (10:9-10). Pablo lo emplea en sentido figurado en Colosenses 3:19, exhortando a los esposos a no ser ásperos ni amargarse contra sus esposas. El término abarca tanto la amargura física del sabor como la amargura emocional en las relaciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4088', 'spa', 'Amargura; disposición áspera y resentida; la raíz venenosa de un sentimiento hostil.', 'El sustantivo πικρία expresa amargura tanto en sentido físico como profundamente moral. En Hechos 8:23, Pedro diagnostica a Simón el Mago como atrapado en la «hiel de amargura», eco veterotestamentario de una corrupción venenosa. Pablo lo incluye entre los vicios que deben abandonarse (Ef 4:31) y cita los Salmos: «su boca está llena de maldición y amargura» (Ro 3:14). Hebreos 12:15 advierte contra una «raíz de amargura» que brota para contaminar a la comunidad. En todas las lenguas, la metáfora de una disposición interior tóxica se mantiene constante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4091', 'spa', 'Pilatos — Poncio Pilato, prefecto romano de Judea que presidió el juicio y la crucifixión de Jesús', 'Πιλᾶτος (Poncio Pilato) es el nombre propio del prefecto romano que gobernó Judea aproximadamente entre los años 26 y 36 d.C. Sus 55 apariciones en el Nuevo Testamento se concentran en los relatos de la Pasión, donde interroga a Jesús, ofrece liberar a Barrabás, se lava las manos y ordena la crucifixión. Lucas 3:1 fecha el ministerio de Juan el Bautista por la gobernación de Pilato, y 1 Timoteo 6:13 preserva la fórmula credal ''que dio testimonio de la buena profesión delante de Poncio Pilato''. Su nombre entró en el Credo de los Apóstoles mismo, convirtiéndolo en uno de los nombres propios de mayor trascendencia teológica del Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4092', 'spa', 'hincharse, inflamarse o distenderse (especialmente por lesión o veneno)', 'Verbo poco frecuente que describe la hinchazón física producida cuando un tejido se inflama o distiende. En Hechos 28:6, los habitantes de Malta esperan que Pablo se hinche tras ser mordido por una víbora, anticipando la reacción corporal típica ante una mordedura venenosa. La evidencia multilingüe (inglés «to-swell-up», español «hincharse», francés «brûlure») recoge tanto la hinchazón como la sensación de ardor asociada a la inflamación. El hecho de que Pablo no sufra ningún efecto demuestra la protección divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4093', 'spa', 'tablilla de escritura pequeña (generalmente recubierta de cera para inscripciones temporales)', 'Forma diminutiva que designa una tablilla de escritura pequeña, generalmente de madera y recubierta de cera para mensajes temporales. En Lucas 1:63, Zacarías usa una de estas tablillas para escribir el nombre de su hijo tras haber quedado mudo. Estas tablillas portátiles eran objetos domésticos comunes en el mundo mediterráneo antiguo, utilizadas para notas rápidas, cartas o, como en el caso de Zacarías, para comunicarse de manera urgente cuando el habla resultaba imposible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4094', 'spa', 'Bandeja, fuente; recipiente plano para servir, especialmente aquel en que fue presentada la cabeza de Juan el Bautista.', 'Sustantivo que designa una bandeja o fuente: un recipiente plano usado para servir alimentos. En el NT adquiere asociaciones siniestras: cuatro de sus cinco apariciones se relacionan con la macabra petición de la cabeza de Juan el Bautista «en una bandeja» (Mt 14:8, 11; Mr 6:25, 28). Esta imagen estremecedora transforma un utensilio común de banquete en símbolo del juramento temerario de Herodes y la crueldad vengativa de Herodías. Lucas 11:39 lo emplea en la reprensión de Jesús a los fariseos, quienes limpian el exterior del «plato» descuidando la rectitud interior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4095', 'spa', 'Beber — consumir líquido; figuradamente, participar del sufrimiento, el juicio o el sustento espiritual', 'πίνω es el verbo griego básico para beber, cubriendo todo el espectro desde el consumo ordinario de agua y vino hasta la metáfora teológica profunda. En el nivel literal aparece en contextos cotidianos: comer y beber a la mesa (Mt 11:18-19; Lc 7:33-34) y dar de beber al sediento (Mt 25:35). En sentido figurado, Jesús lo transforma en verbo de participación pactual: ''Bebed de ella todos, porque esto es mi sangre del pacto'' (Mt 26:27). La ''copa'' que Jesús pregunta si los discípulos pueden beber (Mt 20:22; Mr 10:38) simboliza sufrimiento y martirio. Pablo extiende la imagen al sustento espiritual: ''todos bebieron la misma bebida espiritual'' (1 Co 10:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4096', 'spa', 'gordura, riqueza; metafóricamente, prosperidad o abundancia', 'Originalmente designaba la gordura o riqueza literal de la carne, pero en el uso bíblico adquiere un peso metafórico significativo. En Romanos 11:17, Pablo lo emplea para describir cómo los creyentes gentiles participan de la ''riqueza'' del olivo cultivado, es decir, de las bendiciones del pacto de Israel. La imagen se apoya en una realidad agrícola: las aceitunas grasas y ricas en aceite producen las mejores cosechas, transmitiendo así la idea de abundancia espiritual y prosperidad compartida mediante el pacto de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4097', 'spa', 'Vender; intercambiar bienes, propiedades o personas por dinero en una transacción comercial o legal.', 'Abarca el acto de vender, ya se trate de mercancías, tierras o incluso personas sometidas a servidumbre. El término aparece en parábolas donde un mercader vende todo para comprar la perla de gran precio (Mt 13:46) y en relatos donde un ungüento costoso «pudo haberse vendido» en favor de los pobres (Mt 26:9, Mr 14:5, Jn 12:5). El uso más sobrio surge en Mt 18:25, donde se ordena vender al deudor y su familia para saldar la deuda. Las formas pasivas en diversas lenguas resaltan cómo tanto personas como bienes podían convertirse en objetos de venta en el mundo antiguo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4098', 'spa', 'Caer; desplomarse físicamente, postrarse en adoración, tropezar moralmente o ser destruido', 'πίπτω es uno de los verbos más viscerales del Nuevo Testamento, portando todo el peso de la gravedad, tanto literal como espiritual. En su sentido más físico, describe un gorrión cayendo a tierra (Mt 10:29) o migajas cayendo de la mesa (Mt 15:27). Pero el uso más frecuente es profundamente teológico: postrarse ante Jesús, ante un ángel o ante Dios en adoración y reverencia. Los magos ''se postraron'' ante el niño Cristo (Mt 2:11), y Juan cae a los pies del Señor resucitado en Apocalipsis. El vocablo también se oscurece en registros morales y cósmicos: Pablo advierte ''el que piensa estar firme, mire que no caiga'' (1 Co 10:12), y el estribillo apocalíptico ''¡Caída, caída es Babilonia la grande!'' resuena con el antiguo oráculo de Isaías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4100', 'spa', 'Creer, confiar, tener fe; en voz pasiva: ser encomendado o ser creído; el verbo central del NT para la fe salvífica', 'Este es el verbo definitorio de la teología neotestamentaria: aparece más de 240 veces y abarca todo el espectro desde la confianza inicial hasta la convicción arraigada. Cuando Jesús dice ''el que cree en él'' (Jn 3:16), πιστεύω conlleva el peso de una dependencia personal, no de un mero asentimiento intelectual. La voz pasiva abre un segundo campo semántico: ser encomendado con una comisión (Ro 3:2; 1 Ti 1:11), donde el significado pasa por completo de ''creer'' a ''recibir un encargo''. El árabe emplea consistentemente la raíz ʾ-m-n (آمَنَ) y el coreano 믿다, subrayando la centralidad universal de este concepto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4102', 'spa', 'Fe, confianza, creencia en Dios o en Cristo; también fidelidad o fiabilidad como cualidad de carácter', 'Πίστις es el término teológico por excelencia del Nuevo Testamento: aparece 243 veces para nombrar la respuesta humana esencial a la acción de Dios en Cristo. En su sentido primario abrumador, denota la disposición activa de confianza y creencia — desde la fe que sana (''tu fe te ha salvado'', Mt 9:22) hasta la fe que justifica (Ro 3:28; Gá 2:16) y la fe por la que se contendió como depósito apostólico (Jud 3). Sin embargo, en un puñado de pasajes, πίστις se desplaza hacia una cualidad objetiva: la fidelidad como fruto del Espíritu (Gá 5:22) o la fiabilidad de Dios mismo (Ro 3:3). El español distingue nítidamente ''fe'' de ''fidelidad'', una separación léxica que ilumina la doble naturaleza de esta palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4103', 'spa', 'Fiel, digno de confianza, fiable (pasivo); también creyente, el que cree (activo: el que ejerce la fe)', 'Edificado sobre la raíz πειθ- (''persuadir, confiar''), πιστός presenta dos caras complementarias. En su sentido pasivo —con mucho el más frecuente— describe a alguien o algo digno de confianza: el siervo fiel de las parábolas de Jesús (Mt 24:45; 25:21), los ''dichos fieles'' de las Epístolas Pastorales (1 Ti 1:15) y Dios mismo como πιστός (1 Co 1:9; 10:13). En su sentido activo, πιστός designa al que cree: un creyente, un miembro de la comunidad de fe. Este uso activo emerge claramente en Hechos y las Epístolas: ''los creyentes'' (Hch 10:45), Timoteo como hijo creyente (1 Co 4:17). El español distingue nítidamente ''fiel'' de ''creyente'', haciendo léxicamente visible la distinción de voz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4104', 'spa', 'estar convencido, asegurado o certificado (especialmente mediante enseñanza o evidencia)', 'Este verbo en voz pasiva transmite la idea de estar firmemente persuadido o convencido de algo, generalmente a través de la instrucción o la evidencia. En 2 Timoteo 3:14, Pablo insta a Timoteo a permanecer en aquello de lo que ha sido convencido, lo cual implica una certeza asentada, construida mediante la enseñanza y la experiencia. El término no sugiere un mero acuerdo intelectual, sino una confianza profundamente arraigada que moldea la conducta y el compromiso de vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4105', 'spa', 'Engañar, extraviar o errar de la verdad; activo: inducir al error; medio/pasivo: descarriarse o ser engañado', 'Engañar, extraviar o errar de la verdad; activo: inducir al error; medio/pasivo: descarriarse o ser engañado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4106', 'spa', 'Desviarse de la verdad: error, engaño o creencia falsa; también fraude o impostura deliberada. πλάνη (plane) deriva del verbo πλανάω (''vagar, extravia', 'Desviarse de la verdad: error, engaño o creencia falsa; también fraude o impostura deliberada. πλάνη (plane) deriva del verbo πλανάω (''vagar, extraviar'') y evoca la imagen de alguien perdido fuera del camino verdadero. En nueve de sus diez apariciones en el NT denota el estado de hallarse en error — una ilusión espiritual o moral, como en el ''error de Balaam'' (Judas 11) o la ''operación de error'' que Dios envía a quienes rechazan la verdad (2 Tesalonicenses 2:11). Pablo lo usa en Romanos 1:27 para el ''error'' de la idolatría que recibe en sí mismo su propia retribución. Pero en Mateo 27:64 los principales sacerdotes advierten a Pilato que un segundo ''engaño'' sería peor que el primero — aquí la palabra pasa de la ilusión pasiva al fraude activo y calculado. El español distingue ambos sentidos con claridad: ''error'' para el estado de extravío y ''engaño'' para la maniobra intencional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4107', 'spa', 'errante, vagabundo; metafóricamente, errático o inestable', 'Originalmente describe a quienes vagan de un lugar a otro: viajeros, vagabundos o mercaderes itinerantes. En el uso bíblico adquiere un sentido metafórico de inestabilidad espiritual. En Judas 13, las ''estrellas errantes'' evocan la imagen astronómica antigua de los planetas, cuyos movimientos erráticos contrastaban con las estrellas fijas. La metáfora retrata con fuerza a los falsos maestros como seres inestables, impredecibles y carentes del anclaje firme de la verdad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4108', 'spa', 'Engañador, impostor; quien extravía a otros, especialmente mediante falsas enseñanzas o pretensiones.', 'Adjetivo usado sustantivamente para designar a un engañador o impostor: alguien que activamente extravía a otros. En Mateo 27:63, los principales sacerdotes llaman a Jesús «aquel engañador» ante Pilato, aplicando irónicamente esta etiqueta a quien más temen. Pablo recupera el término con fuerza paradójica en 2 Corintios 6:8: «como engañadores, pero veraces». Primera Timoteo 4:1 advierte sobre «espíritus engañadores», y 2 Juan 1:7 lo emplea dos veces para identificar a quienes niegan la encarnación de Cristo como «el engañador y el anticristo».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4109', 'spa', 'Tabla, piedra plana; superficie de escritura, especialmente tablas de piedra para inscripciones o textos sagrados', 'Este sustantivo designa cualquier objeto plano y ancho, en especial una piedra plana o tabla usada para escribir. Pablo contrasta a sus convertidos de Corinto con una carta escrita no en «tablas de piedra» sino en corazones de carne (2 Co 3:3). Hebreos menciona el arca que contenia «las tablas del pacto» (He 9:4). La palabra evoca las tablas de piedra que Moises recibio en el Sinai, convirtiendose en un simbolo poderoso del antiguo pacto frente al nuevo: la ley externa grabada en roca versus la transformacion interna escrita en corazones vivos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4110', 'spa', 'algo formado o moldeado; una cosa creada o un artefacto', 'Este término designa cualquier cosa que ha sido formada o moldeada, especialmente objetos hechos de arcilla o cera. En Romanos 9:20, Pablo recurre a la metáfora del alfarero y el barro, preguntando si lo que ha sido formado puede cuestionar a su hacedor. La palabra posee tanto un significado literal (un artefacto físico) como un peso teológico profundo (la humanidad como creación de Dios). En la antigüedad, el término abarcaba desde figurillas de arcilla hasta el cuerpo humano mismo, entendido como obra divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4112', 'spa', 'fabricado, ficticio, falso; construido artificialmente para engañar', 'Este adjetivo describía originalmente objetos moldeados o formados (especialmente en arcilla o cera), pero pasó a significar ''fabricado'' o ''ficticio'' en sentido negativo. En 2 Pedro 2:3, los falsos maestros explotan a los creyentes con palabras fingidas: argumentos deliberadamente construidos para engañar en vez de instruir. El término implica una artificialidad calculada, como una estatua que imita la vida pero carece de ella, o un documento falsificado que aparenta autenticidad siendo fundamentalmente falso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4113', 'spa', 'Calle ancha, plaza pública o vía principal de una ciudad; lugar de vida cívica y encuentro comunitario.', 'Sustantivo femenino derivado del adjetivo πλατύς (''ancho''), que designa las calles principales, plazas o espacios abiertos de una ciudad donde transcurre la vida pública. Jesús advierte contra la oración ostentosa «en las esquinas de las calles» (Mt 6:5) y cita proféticamente a Isaías respecto a no clamar «en las plazas» (Mt 12:19). En las parábolas, los siervos son enviados a calles y plazuelas para traer invitados al banquete (Lc 14:21). El término abarca desde callejones amplios hasta espacios abiertos de reunión pública.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4114', 'spa', 'Anchura, amplitud; dimensión espacial que describe la extensión lateral de algo.', 'Sustantivo derivado del adjetivo πλατύς (ancho), πλάτος designa la anchura o amplitud como dimensión espacial. Pablo lo invoca en una oración extraordinaria para que los creyentes comprendan la anchura, longitud, altura y profundidad del amor de Cristo (Ef 3:18), metáfora tetradimensional de un amor que sobrepasa el conocimiento. En Apocalipsis, mide la vasta extensión de la tierra sobre la cual avanzan Gog y Magog (20:9) y las dimensiones iguales de la Nueva Jerusalén cúbica (21:16), eco del Lugar Santísimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4115', 'spa', 'Ensanchar, ampliar; hacer algo mas ancho o espacioso, en sentido literal o figurado', 'Este verbo significa hacer ancho o amplio, ensanchar. Jesus critica a los escribas y fariseos que «ensanchan» sus filacterias para aparentar mayor devocion (Mt 23:5). Pablo dice a los corintios que su corazon «se ha ensanchado» hacia ellos, es decir, se ha abierto con afecto (2 Co 6:11), y les exhorta a que «se ensanchen» tambien ellos en sus corazones hacia el (2 Co 6:13). La palabra funciona tanto en sentido literal, haciendo objetos fisicos mas anchos, como en sentido metaforico, ampliando la capacidad emocional o la disposicion del corazon.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4116', 'spa', 'ancho, amplio, espacioso; extenso en anchura', 'Este adjetivo describe amplitud o anchura física, a menudo con implicaciones morales. En Mateo 7:13, Jesús contrasta la puerta ancha y el camino espacioso que conduce a la perdición con el sendero estrecho que lleva a la vida. La metáfora espacial es poderosa: los caminos anchos acogen multitudes y exigen poco esfuerzo para recorrerlos, mientras que los senderos estrechos demandan atención y cuidado. Lo que parece atractivo y fácil resulta espiritualmente peligroso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4117', 'spa', 'cabello trenzado; peinados elaborados creados al trenzar o entrelazar', 'Este término designaba originalmente cualquier cosa torcida o entretejida, desde zarcillos de vid hasta cestería, pero en el Nuevo Testamento se refiere específicamente a peinados trenzados elaborados. En 1 Timoteo 2:9, Pablo desaconseja los arreglos capilares ostentosos que señalaban riqueza y estatus social. Los peinados antiguos podían ser extraordinariamente complejos, requiriendo horas y a veces esclavas para crearlos, convirtiéndolos en marcadores visibles de posición social y riqueza disponible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4118', 'spa', 'El mayor, la mayoría, muy grande; superlativo de πολύς (mucho/muchos).', 'Forma superlativa de πολύς, πλεῖστος significa «el mayor número», «la mayoría» o «muy grande». Jesús realizó la mayoría de sus obras poderosas en las ciudades a las que dirige sus ayes (Mt 11:20), y en su entrada triunfal una multitud muy numerosa tendió sus mantos en el camino (Mt 21:8). Marcos 4:1 describe la inmensa multitud reunida junto al mar. Pablo lo emplea en 1 Corintios 14:27 para establecer un límite: «a lo sumo» dos o tres deben hablar en lenguas. El término abarca tanto la cantidad máxima como el grado superlativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4119', 'spa', 'Más, mayor (comparativo de πολύς); en cantidad, número, extensión, duración, rango o importancia; sustantivado, ''la mayoría''', 'πλείων es la forma comparativa de πολύς (''mucho, muchos'') y funciona como la palabra principal del Nuevo Testamento para ''más'' en casi toda dimensión: más personas, más tiempo, mayor importancia, mayor extensión. Su versatilidad es engañosa: lo que parece un solo vocablo en realidad recorta varios espacios semánticos distintos. A veces compara cantidades explícitamente (''más de cinco mil'', Mt 14:21). A veces aparece con artículo como sustantivo significando ''la mayoría'' (1 Co 15:6). En los Sinópticos, Jesús lo usa para afirmar superioridad cualitativa: ''algo mayor que el templo está aquí'' (Mt 12:6). El español distingue ''más'' (cuantitativo) de ''mayor'' (evaluativo), revelando la costura semántica que el griego deja sin marcar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4120', 'spa', 'Trenzar, tejer, entrelazar; entrelazar hebras o ramas para formar algo tejido o trenzado', 'Este verbo significa trenzar, tejer o entrelazar. En los tres relatos evangelicos, los soldados romanos «tejieron» o «trenzaron» una corona de espinas y la colocaron sobre la cabeza de Jesus durante su burla (Mt 27:29; Mr 15:17; Jn 19:2). La imagen es vivida: entrelazar espinas punzantes en una cruel parodia de corona real. Aunque el verbo puede aplicarse a cualquier tipo de tejido o trenzado, su uso en el Nuevo Testamento se concentra enteramente en este unico y estremecedor momento de la Pasion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4121', 'spa', 'Aumentar, abundar o multiplicarse; crecer en cantidad, intensidad o grado; tener de sobra.', 'Expresa la idea de crecer más allá de lo esperado: desbordarse, multiplicarse, sobrepasar una medida anterior. Pablo lo emplea de manera contundente en Romanos 5:20 para describir cómo el pecado «abundó» bajo la ley solo para que la gracia «sobreabundara aún más», creando uno de los contrastes teológicos más impactantes del Nuevo Testamento. En otros pasajes describe el amor que abunda (1 Ts 3:12; Fil 4:17), la fe que crece (2 Ts 1:3) y el excedente material (2 Co 8:15). El verbo combina los matices de desbordamiento y multiplicación activa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4122', 'spa', 'Aprovecharse de, explotar, defraudar; obtener ganancia a costa de otro mediante codicia o astucia.', 'Verbo que significa aprovecharse, explotar o defraudar: obtener beneficio a expensas de otro mediante un afán codicioso. Derivado de πλέον (más) + ἔχω (tener), literalmente significa ''tener más'' a costa ajena. Pablo lo usa de forma exclusiva, y sus cinco apariciones revelan su vigilancia pastoral contra la explotación. En 2 Cor 2:11, Satanás podría ''aprovecharse'' de la comunidad. En 2 Cor 7:2 y 12:17-18, Pablo se defiende de acusaciones de explotación económica. En 1 Tesalonicenses 4:6, advierte a los creyentes que no defrauden al hermano en asuntos comerciales o personales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4123', 'spa', 'Persona codiciosa, avara; quien ambiciona más de lo que le corresponde, movido por una avaricia insaciable.', 'Formado a partir de πλέον (más) y ἔχω (tener), πλεονέκτης significa literalmente ''el que tiene más'': una persona que siempre ambiciona más de lo que le corresponde. Pablo incluye al avaro en sus listas de vicios junto a los inmorales y los idólatras (1 Cor 5:10-11; 6:10), lo cual muestra la gravedad con que la iglesia primitiva veía la codicia. En Efesios 5:5 equipara la avaricia con la idolatría, declarando que ningún codicioso tiene herencia en el reino de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4124', 'spa', 'Deseo insaciable de poseer más, codicia — un afán implacable que explota a los demás en busca de ganancia. πλεονεξία (pleonexia) denota un deseo insac', 'Deseo insaciable de poseer más, codicia — un afán implacable que explota a los demás en busca de ganancia. πλεονεξία (pleonexia) denota un deseo insaciable de poseer más de lo que corresponde, a menudo a costa de otros. En Lucas 12:15, Jesús advierte contra toda forma de πλεονεξία, vinculándola con la ilusión de que la vida consiste en la abundancia de bienes. Pablo la agrupa con la inmoralidad sexual y la idolatría como rasgos del viejo hombre (Efesios 4:19; 5:3; Colosenses 3:5), y en 2 Pedro 2:3 los falsos maestros explotan a los creyentes con palabras fingidas movidos por la πλεονεξία. Los términos ''avaricia'' y ''codicia'' captan la cualidad agresiva y acaparadora que distingue este vicio del simple deseo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4125', 'spa', 'Costado del cuerpo, zona de las costillas; la parte lateral del torso, especialmente como herida en la Pasión y la Resurrección.', 'Πλευρά significa «costado», específicamente la zona lateral del torso humano cerca de las costillas. Aunque en el griego clásico podía referirse a las costillas mismas, el Nuevo Testamento lo emplea exclusivamente para el costado del cuerpo de Jesús. Un soldado lo atraviesa con una lanza en la crucifixión (Juan 19:34; posiblemente Mt 27:49), y el Cristo resucitado muestra su costado herido a los discípulos como prueba de identidad (Juan 20:20, 25, 27). La exigencia de Tomás de poner su mano «en su costado» convierte a πλευρά en una palabra vinculada para siempre con la realidad tangible de la resurrección. El español «costado» y el francés «côté» conservan fielmente este significado corporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4126', 'spa', 'πλέω — navegar, viajar en barco a través de una extensión de agua.', 'El verbo πλέω denota navegar o viajar por mar, el término griego básico para el desplazamiento marítimo. Las seis apariciones neotestamentarias describen viajes literales por agua: los discípulos cruzando el mar de Galilea (Lucas 8:23) y los diversos viajes misioneros de Pablo en barco (Hechos 21:3; 27:2, 6, 24). La palabra no tiene extensión metafórica en el NT: es concreta y práctica. El español «navegar», el francés «naviguer» y el alemán «segeln» convergen en el mismo sentido marítimo directo, reflejo de un mundo donde la navegación era el medio principal de transporte a larga distancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4127', 'spa', 'Golpe, azote o llaga; plaga o calamidad divina; herida, especialmente herida mortal.', 'Golpe, azote o llaga; plaga o calamidad divina; herida, especialmente herida mortal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4128', 'spa', 'Multitud, muchedumbre o gran número; una gran cantidad de personas reunidas, u ocasionalmente de cosas', 'Multitud, muchedumbre o gran número; una gran cantidad de personas reunidas, u ocasionalmente de cosas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4129', 'spa', 'Multiplicar o hacer crecer en número; en voz pasiva, crecer, abundar o ser multiplicado. Un vocablo del campo semántico del crecimiento y la abundanci', 'Multiplicar o hacer crecer en número; en voz pasiva, crecer, abundar o ser multiplicado. Un vocablo del campo semántico del crecimiento y la abundancia, usado tanto para la acción soberana de Dios al multiplicar personas o recursos como para cosas que crecen por sí mismas. Lucas narra la expansión explosiva de la iglesia primitiva con este verbo: la palabra de Dios ''se multiplicaba'' y los discípulos ''crecían'' (Hch 6:7; 9:31; 12:24). En su sentido transitivo, Dios es el agente que multiplica, como en la promesa a Abraham (He 6:14) y en la oración de Pablo pidiendo que Dios multiplique la semilla de los corintios para la siembra (2 Co 9:10). El saludo epistolar ''gracia y paz os sean multiplicadas'' (1 P 1:2; 2 P 1:2; Jud 1:2) se ha convertido en un sello distintivo de las cartas apostólicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4130', 'spa', 'Llenar o ser llenado — con una sustancia, emoción o el Espíritu Santo; también cumplir o completar un período de tiempo.', 'Llenar o ser llenado — con una sustancia, emoción o el Espíritu Santo; también cumplir o completar un período de tiempo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4132', 'spa', 'inundación, diluvio, crecida; marea creciente de aguas desbordadas', 'Este término describe la embestida arrolladora del agua en una inundación o la crecida de una marea. En Lucas 6:48, Jesús lo utiliza para representar la riada violenta que pone a prueba los cimientos de una casa. La imagen resonaría profundamente en audiencias mediterráneas familiarizadas con las crecidas estacionales y las marejadas destructivas. El término capta tanto el volumen del agua como su fuerza implacable, una metáfora perfecta de las pruebas de la vida que revelan si la fe está edificada sobre terreno firme.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4133', 'spa', 'Conjunción adversativa ''pero, sin embargo, no obstante''; también preposicional ''excepto, solo, aparte de''', 'Conjunción adversativa ''pero, sin embargo, no obstante''; también preposicional ''excepto, solo, aparte de''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4134', 'spa', 'El adjetivo πλήρης (''lleno'') aparece a lo largo del Nuevo Testamento describiendo tanto la plenitud concreta como la abstracta. Las canastas están ''ll', 'El adjetivo πλήρης (''lleno'') aparece a lo largo del Nuevo Testamento describiendo tanto la plenitud concreta como la abstracta. Las canastas están ''llenas'' de los pedazos sobrantes tras las alimentaciones milagrosas (Mt 14:20, 15:37, Mr 8:19-20) y una espiga crece ''llena'' en el tallo (Mr 4:28). Más llamativamente, la palabra caracteriza a personas colmadas de cualidades espirituales: Jesús está ''lleno del Espíritu Santo'' (Lc 4:1), Esteban está ''lleno de fe y de poder'' (Hch 6:8) y Tabita está ''llena de buenas obras'' (Hch 9:36). Las traducciones multilingües son notablemente uniformes -- ''lleno/llena'', ''plein'', ''voll'' -- en todas las apariciones, reflejando el significado central único del adjetivo aplicado a distintos ámbitos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4135', 'spa', 'Estar plenamente convencido o completamente seguro; también cumplir, llevar a cabo o realizar por completo.', 'Πληροφορέω encierra la idea raíz de «llenar hasta el tope» y en el NT se despliega en dos aplicaciones distintas. Por un lado, describe el estado interior de estar completamente convencido o plenamente seguro: Abraham estaba «plenamente persuadido» de que Dios podía cumplir lo prometido (Rom 4:21), y Pablo insiste en que cada creyente debe estar «plenamente convencido en su propia mente» sobre asuntos disputables (Rom 14:5). Por otro lado, designa la realización plena de los propósitos divinos: Lucas abre su Evangelio mencionando hechos «plenamente cumplidos entre nosotros» (Lc 1:1), y Pablo encarga a Timoteo «cumplir» su ministerio (2 Ti 4:5). El español distingue ambos usos con claridad: «plenamente convencido» para la convicción y «cumplir» para la realización.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4136', 'spa', 'Plena certeza, completa convicción; la confianza firme y arraigada que nace de una fe profunda.', 'Derivado de πληροφορέω (llenar por completo), πληροφορία designa la plenitud de convicción o certeza absoluta que brota de una fe profunda. Pablo habla de la ''plena certeza de entendimiento'' necesaria para conocer el misterio de Cristo (Col 2:2) y recuerda cómo el evangelio llegó a los tesalonicenses no solo de palabra, sino con poder y plena certeza (1 Tes 1:5). Hebreos exhorta a los creyentes hacia la plena certeza de la esperanza (6:11) y de la fe (10:22), acercándose a Dios con corazón sincero y confianza inquebrantable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4137', 'spa', 'Llenar, colmar; cumplir profecía o completar un propósito; en voz pasiva, ser lleno del Espíritu, gozo o contenido.', 'πληρόω es uno de los verbos teológicamente más fecundos del Nuevo Testamento, pues conecta el acto físico de llenar un recipiente con el acto divino de llevar la Escritura a su cumplimiento. La fórmula reiterada de Mateo, ''para que se cumpliese lo dicho por el profeta'' (Mat 1:22; 2:15), emplea precisamente este verbo, convirtiéndolo en el eje entre la promesa veterotestamentaria y la realización neotestamentaria. Sin embargo, la misma raíz llena una casa de fragancia (Jn 12:3), llena a los discípulos del Espíritu Santo en Pentecostés (Hch 2:4) y llena una red de peces (Mat 13:48). Las lenguas modernas confirman los límites semánticos: el árabe distingue entre tamm (''completarse'') y mala''a (''llenar físicamente''), y el coreano separa 이루어지다 (''cumplirse'') de 채우다 (''llenar un recipiente'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4138', 'spa', 'Πλήρωμα es uno de los términos teológicos más ricos del Nuevo Testamento. Juan declara que de la plenitud de Cristo los creyentes han recibido gracia ', 'Πλήρωμα es uno de los términos teológicos más ricos del Nuevo Testamento. Juan declara que de la plenitud de Cristo los creyentes han recibido gracia sobre gracia (Jn 1:16), y Pablo afirma que en Cristo ''habita corporalmente toda la plenitud de la Deidad'' (Col 2:9). Sin embargo, la palabra también tiene un lado terrenal y concreto: las doce canastas de pedazos sobrantes tras la alimentación de los cinco mil son literalmente la ''plenitud'' de lo que quedó (Mr 6:43). Pablo reúne ambos registros cuando escribe que el amor es el ''cumplimiento'' de la ley (Ro 13:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4139', 'spa', 'Cercano, próximo; como sustantivo, ''el prójimo'' -- el ser humano hacia quien se tiene una obligación moral. Originalmente un adjetivo espacial que sig', 'Cercano, próximo; como sustantivo, ''el prójimo'' -- el ser humano hacia quien se tiene una obligación moral. Originalmente un adjetivo espacial que significaba ''cerca'' o ''próximo a,'' esta palabra experimentó una notable transformación teológica. En el griego clásico describía proximidad física -- campos vecinos, pueblos cercanos. Pero en la traducción de la Septuaginta de Levítico 19:18 y a lo largo del NT, ὁ πλησίον (''el que está cerca'') se convierte en el ''prójimo'' ético -- la persona hacia quien se ordena el amor (Mt 22:39; Ro 13:9; Gá 5:14). El español prójimo, el francés prochain y el alemán Nächster conservan este desplazamiento de la cercanía espacial a la cercanía relacional. Solo en Juan 4:5, donde la ciudad samaritana está ''cerca'' de un terreno, sobrevive en el NT el sentido locativo original.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4140', 'spa', 'saciedad, indulgencia, hartazgo; estado de llenura excesiva (especialmente de comida)', 'Este término denota el estado de estar completamente lleno o satisfecho, a menudo hasta el exceso. Aunque puede significar simplemente saciedad, frecuentemente conlleva connotaciones negativas de sobreindulgencia o hartazgo. En Colosenses 2:23, Pablo critica las prácticas ascéticas que parecen sabias pero resultan inútiles ''contra los apetitos de la carne''. La ironía es aguda: las restricciones corporales severas no frenan realmente los apetitos carnales, solo los redirigen hacia otras formas de gratificación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4141', 'spa', 'golpear, herir, azotar; infligir un golpe o herida con fuerza', 'Este verbo describe la acción de golpear o herir con fuerza, ya sea en combate, castigo o juicio divino. En Apocalipsis 8:12, una tercera parte del sol, la luna y las estrellas son heridas durante el juicio de la cuarta trompeta, provocando oscuridad cósmica parcial. El término transmite el impacto violento y sus consecuencias. En el griego antiguo, esta palabra se usaba para todo tipo de golpes, desde los del campo de batalla hasta los del martillo del herrero, enfatizando la fuerza y el efecto del impacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4142', 'spa', 'Barquita, bote pequeño; embarcación de tamaño reducido, menor que una nave, usada cerca de la orilla en el mar de Galilea.', 'Diminutivo de πλοῖον (barco/nave), designa una embarcación pequeña o bote: el tipo de barca usada para trayectos cortos en el mar de Galilea. En Marcos 3:9, Jesús pide que le tengan lista una barquita para que la multitud no lo aplaste. En Juan 6:22-24, la multitud nota que solo había una barquita en la orilla tras el milagro de la multiplicación, y al día siguiente llegaron otras barcas de Tiberias. Juan 21:8 sitúa a los discípulos en la barquita arrastrando la red llena de peces hacia la orilla. El diminutivo español ''barquita'' refleja con encanto el sufijo diminutivo griego -αριον.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4143', 'spa', 'Embarcación: barca pequeña o lancha de pesca en aguas interiores; también navío mayor para travesías mediterráneas.', 'Derivado del verbo πλέω (''navegar''), πλοῖον es el término general del Nuevo Testamento para toda embarcación, abarcando desde la barca de pesca de Pedro en el mar de Galilea hasta los navíos de carga en que Pablo cruzó el Mediterráneo. Los Evangelios concentran el sentido de barca pequeña: las embarcaciones de los discípulos figuran en relatos de tormentas (Mat 8:23-24), pescas milagrosas (Lc 5:2-7) y Jesús caminando sobre el agua (Mat 14:22-33). Hechos cambia el registro por completo: πλοῖον designa ahora un navío de altura azotado por la tempestad en alta mar (Hch 27). El alemán distingue Boot (''bote'') de Schiff (''barco''), y el francés bateau de navire, reflejando este mismo cambio de escala.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4144', 'spa', 'Viaje por mar, navegación; el acto de viajar en barco o la temporada y condiciones propicias para navegar', 'Este sustantivo designa un viaje por mar o el acto de navegar. Tras completar la travesía desde Tiro, Pablo y sus compañeros llegaron a Tolemaida (Hch 21:7). Como había pasado mucho tiempo y la navegación ya era peligrosa (después del ayuno), Pablo advierte contra continuar el viaje (Hch 27:9-10). La palabra puede referirse al trayecto marítimo en sí, a la temporada apropiada para navegar o a las condiciones de una travesía particular. La navegación mediterránea antigua era altamente estacional, lo que hacía del momento oportuno un factor decisivo para viajar con seguridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4145', 'spa', 'Rico, acaudalado; que posee abundantes recursos materiales. Usado como adjetivo y sustantivo para personas adineradas.', 'Rico, acaudalado; que posee abundantes recursos materiales. Usado como adjetivo y sustantivo para personas adineradas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4146', 'spa', 'Ricamente, abundantemente; de manera generosa y desbordante.', 'Adverbio derivado del adjetivo πλούσιος (rico, acaudalado), que describe la manera en que algo se da o se experimenta: no con escasez, sino con generosa abundancia. Pablo exhorta a los creyentes a que la palabra de Cristo habite en ellos ''ricamente'' (Col 3:16), y Dios derrama el Espíritu ''abundantemente'' por medio de Jesucristo (Tit 3:6). El término transmite una cualidad de generosidad divina que desborda más allá de la mera suficiencia, reflejando la plenitud con que Dios concede sus dones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4147', 'spa', 'Ser o hacerse rico, ya sea en riqueza material o en bendición espiritual y gracia divina. Este verbo abarca todo el espectro del enriquecimiento, desd', 'Ser o hacerse rico, ya sea en riqueza material o en bendición espiritual y gracia divina. Este verbo abarca todo el espectro del enriquecimiento, desde acumular posesiones terrenales hasta recibir la generosidad abundante de Dios. En el plano material, los mercaderes del Apocalipsis ''se enriquecieron'' con el lujo de Babilonia (Ap 18:3, 15, 19), y Jesús advierte contra quien ''atesora para sí mismo'' pero no es rico para con Dios (Lc 12:21). En el plano espiritual, la paradoja impactante de Pablo en 2 Corintios 8:9 gira en torno a este verbo: Cristo ''se hizo pobre para que vosotros, por su pobreza, fueseis enriquecidos.'' La trágica autoevaluación de la iglesia de Laodicea, ''me he enriquecido'' (Ap 3:17), mezcla irónicamente ambos sentidos: eran prósperos materialmente pero espiritualmente miserables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4148', 'spa', 'Enriquecer, hacer rico; proveer abundancia o hacer próspero a alguien, material o espiritualmente', 'Este verbo significa hacer rico o enriquecer a alguien. Pablo recuerda a los corintios que fueron «enriquecidos» en Cristo en todo, en toda palabra y conocimiento (1 Co 1:5). Describe a personas piadosas que, siendo pobres, «enriquecen a muchos» mediante el evangelio (2 Co 6:10). Les asegura que, al ser «enriquecidos» en todo para toda generosidad, la acción de gracias rebosará (2 Co 9:11). Aunque la palabra puede aplicarse a la riqueza material, Pablo la emplea de manera constante para el enriquecimiento espiritual: gracia, dones y generosidad que fluyen de la abundancia de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4149', 'spa', 'Riquezas, riqueza — tanto abundancia material como, metafóricamente, la plenitud inconmensurable de la gracia y gloria divinas.', 'Riquezas, riqueza — tanto abundancia material como, metafóricamente, la plenitud inconmensurable de la gracia y gloria divinas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4150', 'spa', 'Lavar, limpiar lavando; lavar ropa, telas o redes, a diferencia de bañar el cuerpo', 'Este verbo significa lavar o limpiar, especialmente ropa, telas o lienzos, a diferencia de bañarse (λούομαι) o lavarse las manos (νίζω). Unos pescadores estaban «lavando» sus redes junto al lago cuando Jesús los llamó (Lc 5:2). La gran multitud en Apocalipsis ha «lavado» sus vestiduras y las ha emblanquecido en la sangre del Cordero (Ap 7:14; 22:14). La palabra enfatiza la limpieza de telas, lo cual se convierte en una poderosa metáfora en Apocalipsis: vestiduras hechas blancas no por lejía, sino por sangre sacrificial, pureza mediante la expiación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4151', 'spa', 'Espíritu, espíritu; el Espíritu Santo o Espíritu de Dios; también ser espiritual, espíritu humano, viento o aliento vital', 'Πνεῦμα es una de las palabras de mayor trascendencia teológica en el Nuevo Testamento, y su campo semántico — desde el viento físico hasta la Tercera Persona de la Trinidad — recapitula todo el arco veterotestamentario del hebreo רוּחַ. De sus 383 apariciones, la inmensa mayoría (370) se refiere al Espíritu Santo o Espíritu de Dios, lo que refleja cuán profundamente la pneumatología permea el testimonio neotestamentario. Con todo, la palabra nunca abandona del todo sus raíces terrenales: en Juan 3:8 Jesús explota el doble sentido de πνεῦμα como ''viento'' y ''Espíritu'' en una sola frase, y en 2 Tesalonicenses 2:8 el ''soplo'' de la boca del Señor destruye al inicuo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4152', 'spa', 'Espiritual; perteneciente al Espíritu Santo, al ámbito divino invisible o a los dones otorgados por el Espíritu.', 'Espiritual; perteneciente al Espíritu Santo, al ámbito divino invisible o a los dones otorgados por el Espíritu.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4154', 'spa', 'Soplar (dicho del viento); describe el movimiento del aire o el viento, a veces con matices simbólicos.', 'Verbo griego básico para el soplo del viento, usado en el NT tanto para fenómenos atmosféricos naturales como con profundidad teológica. En la parábola de los dos constructores, es el viento el que «sopló» contra cada casa (Mateo 7:25, 27). De modo especialmente memorable, Jesús le dice a Nicodemo que el viento «sopla donde quiere» (Juan 3:8), empleando la realidad física del viento como analogía del movimiento soberano del Espíritu — un juego de palabras posible por el doble sentido de πνεῦμα. Todas las lenguas confirman un único sentido concreto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4155', 'spa', 'Ahogar, estrangular, sofocar; privar de respiración o de vida por constricción', 'Este verbo significa ahogar, estrangular o sofocar, es decir, cortar la respiración. En la parábola de Jesús, los espinos crecieron y «ahogaron» la semilla (Mt 13:7). En la parábola del siervo despiadado, el hombre agarra a su consiervo y comienza a «ahogarlo» exigiendo el pago (Mt 18:28). Cuando los demonios lanzaron los cerdos al mar, estos «se ahogaron» (Mr 5:13). La palabra retrata vívidamente la sofocación, ya sea por estrangulamiento, ahogamiento o por ser asfixiado entre espinos, una asfixia tanto física como espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4156', 'spa', 'Estrangulado, ahogado; carne de animal matado por estrangulación sin desangrar', 'Este adjetivo describe algo estrangulado o matado por asfixia, en particular la carne de animales que no fueron sacrificados correctamente, es decir, sin que se les drenara la sangre. El decreto del concilio de Jerusalén dirigido a los creyentes gentiles incluye abstenerse de lo ofrecido a ídolos, de sangre y de «lo estrangulado» (Hch 15:20, 29; 21:25). La ley judía exigía que la sangre se drenara al sacrificar un animal; comer carne «estrangulada» violaba este principio. La prohibición respeta la conciencia judía y preserva la unidad en la iglesia primitiva de composición mixta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4158', 'spa', 'túnica talar, vestidura que llega hasta los pies; prenda ceremonial de cuerpo entero', 'Este adjetivo describe una vestidura que llega hasta los pies, típicamente una túnica larga que denota dignidad, cargo u oficio ceremonial. En Apocalipsis 1:13, el Cristo glorificado viste una túnica talar que evoca las vestiduras del sumo sacerdote, señalando su condición real y sacerdotal. En la cultura mediterránea antigua, las túnicas largas distinguían a sacerdotes, reyes y personas de alto rango de los trabajadores comunes, quienes vestían túnicas más cortas y prácticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4159', 'spa', 'De dónde, desde dónde: adverbio interrogativo de lugar, origen o causa, que a menudo expresa asombro', 'De dónde, desde dónde: adverbio interrogativo de lugar, origen o causa, que a menudo expresa asombro');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4160', 'spa', 'Hacer, realizar, obrar; producir, crear; causar; pasar tiempo; celebrar; cometer', 'El verbo de acción más versátil del Nuevo Testamento: cubre todo el espectro de la actividad humana, desde el simple hacer hasta el crear con propósito. Aparece 573 veces expresando desde la realización de milagros (lo que Jesús continuamente ''hacía'') hasta la comisión de delitos, desde producir fruto hasta pasar tiempo en un lugar. Su campo semántico se extiende desde la construcción física (enderezar caminos) hasta la causación abstracta (hacer discípulos) y la duración temporal (pasar tres meses). Como el español ''hacer'', su significado se cristaliza solo en contexto, pero esa misma flexibilidad lo convierte en el verbo comodín para describir cómo actúan Jesús y sus seguidores en el mundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4162', 'spa', 'acción, práctica, ejecución; el cumplimiento o realización concreta de algo', 'Este término denota el acto de hacer o ejecutar algo, enfatizando la acción y la realización concreta por encima de la mera intención. En Santiago 1:25, se contrasta con el mero escuchar: la bendición llega a quien persevera en el hacer, no solo en el oír. El griego antiguo distinguía entre poiesis (creación) y praxis (acción), pero en el uso neotestamentario el enfoque recae sobre la práctica efectiva. La fe verdadera se expresa en obras concretas, no en una profesión vacía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4163', 'spa', 'Hacedor o ejecutor de acciones, especialmente de la ley o la palabra de Dios; también poeta o compositor literario en el uso clásico.', 'Ποιητής significa literalmente «el que hace», y sus dos acepciones en el NT reflejan el recorrido de la palabra desde el mundo literario griego hasta el discurso moral judeocristiano. Santiago la emplea para desafiar a sus lectores: «Sed hacedores de la palabra, no tan solo oidores» (Stg 1:22), y Pablo contrasta a los meros oidores de la ley con sus hacedores (Rom 2:13). Sin embargo, en Hch 17:28, cuando Pablo se dirige a los filósofos atenienses, recurre al sentido clásico y cita a «algunos de vuestros propios poetas» (ποιηταί), un hábil movimiento retórico que tiende un puente entre la cultura literaria griega y el mensaje del evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4164', 'spa', 'Diverso, variado, multiforme — que describe una rica multiplicidad de clases o formas. Adjetivo que significa ''de muchas clases'' o ''diversificado'', ap', 'Diverso, variado, multiforme — que describe una rica multiplicidad de clases o formas. Adjetivo que significa ''de muchas clases'' o ''diversificado'', aplicado tanto a aflicciones como a bendiciones divinas. En los relatos de sanidad, Jesús cura a los afligidos con diversas enfermedades (Mateo 4:24; Marcos 1:34; Lucas 4:40), donde la palabra subraya la enorme diversidad de dolencias. Pero el mismo término describe la multiforme gracia de Dios (1 Pedro 4:10) y las variadas pruebas que ponen a prueba la fe (Santiago 1:2). Hebreos 2:4 habla de los diversos milagros con que Dios confirma el evangelio. El campo semántico abarca así tanto el sufrimiento como el esplendor — todo aquello que es multiforme.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4165', 'spa', 'Pastorear, apacentar un rebaño; en sentido figurado, guiar, gobernar o ejercer cuidado pastoral sobre personas. Tomado del mundo cotidiano del pastore', 'Pastorear, apacentar un rebaño; en sentido figurado, guiar, gobernar o ejercer cuidado pastoral sobre personas. Tomado del mundo cotidiano del pastoreo palestino, este verbo posee una rica doble vida en el Nuevo Testamento. En su sentido literal describe la labor de cuidar y apacentar ovejas (Lucas 17:7; 1 Corintios 9:7). Con mucha mayor frecuencia, sin embargo, se emplea como metáfora del liderazgo espiritual y del gobierno mesiánico. Jesús encarga a Pedro ''pastorea mis ovejas'' (Juan 21:16), y Apocalipsis presenta al Cristo resucitado pastoreando las naciones con vara de hierro (Apocalipsis 2:27; 19:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4166', 'spa', 'Pastor -- el que cuida un rebaño; se usa literalmente para los cuidadores de ovejas y figuradamente para los líderes espirituales. ποιμήν significa pa', 'Pastor -- el que cuida un rebaño; se usa literalmente para los cuidadores de ovejas y figuradamente para los líderes espirituales. ποιμήν significa pastor, el que guía, alimenta y protege un rebaño de ovejas. Sus 18 apariciones en el Nuevo Testamento se dividen en un grupo literal en los relatos de la natividad y un grupo figurado en la enseñanza de Jesús y las epístolas, donde ambos registros se iluminan mutuamente. Los pastores de Belén que ''velaban sus rebaños de noche'' (Lc 2:8, 15, 18, 20) son los primeros en recibir el anuncio angélico del nacimiento del Mesías -- una inversión social, ya que los pastores eran considerados de bajo estatus y ritualmente marginales. Jesús se identifica como ''el buen pastor'' que da su vida por las ovejas (Jn 10:2, 11-12, 14, 16), transformando la imagen pastoral en un título cristológico de autosacrificio. Mira a las multitudes con compasión porque son ''como ovejas sin pastor'' (Mt 9:36; Mr 6:34), evocando la denuncia veterotestamentaria de los líderes fallidos de Israel. La profecía de Zacarías ''hiere al pastor y se dispersarán las ovejas'' se aplica al arresto de Jesús (Mt 26:31; Mr 14:27). Efesios 4:11 enumera ''pastores y maestros'' como dones de Cristo a la iglesia, y Hebreos 13:20 llama al Jesús resucitado ''el gran pastor de las ovejas.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4167', 'spa', 'Rebaño; grupo de ovejas o cabras, usado metafóricamente para el pueblo de Dios bajo el cuidado de un pastor.', 'Sustantivo que designa un rebaño, propiamente de ovejas, y que se extiende metafóricamente a la comunidad de creyentes bajo cuidado pastoral. En Mt 26:31, Jesús cita Zac 13:7: «Heriré al pastor y las ovejas del rebaño serán dispersadas», aplicando la profecía a su propio arresto y la huida de los discípulos. Lc 2:8 lo sitúa en la natividad: pastores que velaban de noche sobre su rebaño. Jn 10:16 contiene la visión de unidad de Jesús: «habrá un solo rebaño y un solo pastor». Pablo lo emplea en 1 Co 9:7 para defender el sustento apostólico: «¿Quién apacienta un rebaño y no bebe de su leche?».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4168', 'spa', 'Rebañito, pequeño rebaño; grupo reducido de ovejas o cabras, usado metafóricamente de la comunidad de discípulos de Cristo.', 'Diminutivo de ποίμνη (rebaño), que transmite ternura e intimidad: un «pequeño rebaño». En Lc 12:32, Jesús consuela a sus discípulos con las memorables palabras: «No temáis, rebañito (ποίμνιον), porque a vuestro Padre le ha placido daros el reino». Los demás usos en Hch 20:28-29 y 1 Pe 5:2-3 se dirigen a los líderes de la iglesia como pastores que cuidan del rebaño de Dios. La forma diminutiva subraya la vulnerabilidad y al mismo tiempo la dignidad de esta comunidad pequeña pero destinada al reino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4169', 'spa', 'Pronombre interrogativo que pregunta ''¿cuál?'' o ''¿de qué clase?'', indagando la identidad o la naturaleza cualitativa.', 'Pronombre interrogativo que pregunta ''¿cuál?'' o ''¿de qué clase?'', indagando la identidad o la naturaleza cualitativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4170', 'spa', 'Hacer guerra, pelear, combatir; se usa tanto del conflicto cósmico apocalíptico como de la contienda humana.', 'Verbo de conflicto armado y guerra, empleado en el NT casi exclusivamente en la imaginería bélica cósmica de Apocalipsis y una vez en el diagnóstico moral de Santiago. En Apocalipsis describe al dragón haciendo guerra contra la descendencia de la mujer (Apocalipsis 12:7), la invencibilidad aterradora de la bestia — «¿quién puede hacer guerra contra ella?» (Apocalipsis 13:4) — y la propia guerra de Cristo con la espada de su boca (Apocalipsis 2:16). Santiago lo reutiliza incisivamente para la contienda interpersonal: «peleáis y hacéis guerra» (Santiago 4:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4171', 'spa', 'Guerra, batalla, conflicto armado -- hostilidad militar organizada entre fuerzas opuestas, ya sea literal o apocalíptica. πόλεμος es la palabra griega', 'Guerra, batalla, conflicto armado -- hostilidad militar organizada entre fuerzas opuestas, ya sea literal o apocalíptica. πόλεμος es la palabra griega para guerra o batalla, raíz de la cual el español deriva ''polémica.'' Las 18 apariciones en el Nuevo Testamento se refieren a conflictos armados, aunque la escala varía desde un rey que calcula si puede enfrentar a un ejército que se aproxima (Lc 14:31) hasta las guerras apocalípticas del Apocalipsis. El discurso del Monte de los Olivos de Jesús advierte a los discípulos que oirán ''de guerras y rumores de guerras'' como señales del fin pero aún no el fin mismo (Mt 24:6; Mr 13:7; Lc 21:9). Santiago pregunta célebremente: ''¿De dónde vienen las guerras y los conflictos entre vosotros?'' y los atribuye a los deseos interiores que combaten en los miembros (Stg 4:1). En Apocalipsis, πόλεμος se convierte en el lenguaje del combate cósmico: guerra en el cielo cuando Miguel lucha contra el dragón (Ap 12:7, 17), la bestia haciendo guerra contra los santos (Ap 13:7; 19:19), y la reunión final para la guerra del gran día del Dios Todopoderoso (Ap 16:14; 20:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4172', 'spa', 'Ciudad, pueblo; asentamiento urbano habitado, ya sea nombrado o genérico', 'Πόλις es la palabra griega estándar para ciudad o pueblo, y en el Nuevo Testamento ancla el marco geográfico de la narrativa evangélica. Jesús llora sobre Jerusalén como πόλις (Mt 23:37), nace en la πόλις de Belén (Lc 2:4) y enseña por las ciudades de Galilea (Mt 9:35). La palabra también porta un peso escatológico en Hebreos 11:10 y Apocalipsis 21:2, donde la ciudad celestial se convierte en la morada definitiva de Dios con la humanidad. Las traducciones emplean uniformemente su vocablo básico para ciudad: ''ciudad'', ''ville'', ''Stadt'', ''kota''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4175', 'spa', 'ciudadanía, comunidad política; el conjunto de ciudadanos o los derechos y deberes que les corresponden', 'Originalmente designaba la realidad concreta de un gobierno o el cuerpo colectivo de ciudadanos, pero con el tiempo pasó a significar la ciudadanía misma o la comunidad política a la que uno pertenece. En Filipenses 3:20, Pablo declara que la ciudadanía de los creyentes está en el cielo, no en estructuras políticas terrenales. Esto era revolucionario en el mundo romano, donde la ciudadanía determinaba la identidad, los derechos y la lealtad. Pablo reorienta la fidelidad primaria de los creyentes hacia una polis celestial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4177', 'spa', 'Ciudadano; miembro de una ciudad o comunidad política con reconocida condición cívica.', 'Designa a una persona que pertenece a una ciudad determinada (πόλις) y goza de sus derechos y responsabilidades. En las parábolas de Lucas, el término describe a los conciudadanos de un noble (Lc 19:14) y a un hacendado local (Lc 15:15). Pablo reivindica su ciudadanía de «una ciudad no insignificante»: Tarso (Hch 21:39). En Hebreos 8:11 aparece en la promesa del nuevo pacto, donde cada ciudadano conocerá al Señor. El vocablo siempre presupone una identidad comunitaria y cívica, no la mera residencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4178', 'spa', 'A menudo, muchas veces, frecuentemente -- adverbio que indica una acción repetida o habitual. πολλάκις es un adverbio temporal que significa ''muchas v', 'A menudo, muchas veces, frecuentemente -- adverbio que indica una acción repetida o habitual. πολλάκις es un adverbio temporal que significa ''muchas veces'' o ''a menudo,'' derivado de πολύς (''mucho''). Sus 18 apariciones en el Nuevo Testamento marcan consistentemente una acción repetida o una ocurrencia habitual. Los Evangelios lo usan para describir el tormento recurrente de un muchacho endemoniado que era arrojado ''muchas veces'' al fuego y al agua (Mt 17:15; Mr 9:22), y un endemoniado que ''muchas veces'' había sido atado con cadenas (Mr 5:4). Juan 18:2 señala que Jesús se reunía ''a menudo'' con sus discípulos en Getsemaní -- un detalle discreto que explica el conocimiento de Judas sobre el lugar. Pablo lo emplea autobiográficamente para catalogar sus sufrimientos repetidos: ''en viajes muchas veces, en peligros de aguas muchas veces'' (2 Co 11:26-27), y menciona sus planes ''muchas veces'' frustrados de visitar Roma (Ro 1:13). Hebreos 6:7 lo usa para la lluvia que cae ''muchas veces'' sobre la tierra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4179', 'spa', 'muchas veces más, múltiple; multiplicado varias veces', 'Este adjetivo expresa multiplicación: recibir de vuelta muchas veces más de lo que se dio o invirtió. En Lucas 18:30, Jesús promete que quienes sacrifican por el reino recibirán muchísimo más en esta vida presente, además de la vida eterna. El término sugiere no una simple duplicación, sino una multiplicación abundante, enfatizando la respuesta generosa de Dios al sacrificio fiel. Lo que los creyentes entregan por causa de Cristo les es devuelto multiplicado de maneras que ellos mismos jamás podrían haber orquestado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4180', 'spa', 'palabrería, verborrea; uso excesivo de palabras o repeticiones vanas en la oración', 'Este término compuesto significa literalmente ''muchas palabras'' y denota un hablar verboso o extenso. En Mateo 6:7, Jesús advierte contra las prácticas de oración paganas que dependen de la ''palabrería'', es decir, la suposición de que el mero volumen o la repetición obligará a Dios a responder. La preocupación no es la duración de la oración en sí, sino el enfoque mecánico y casi mágico que trata a Dios como alguien manipulable mediante fórmulas verbales. La oración eficaz requiere relación, no verborrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4181', 'spa', 'en muchas partes, en diversas porciones; de manera fragmentaria o progresiva', 'Este adverbio describe algo que ocurre en múltiples partes o porciones, sugiriendo una revelación fragmentaria e incremental. En Hebreos 1:1, caracteriza cómo Dios habló a los padres: en muchas partes y de muchas maneras a través de los profetas, en contraste con la palabra completa y definitiva pronunciada en su Hijo. El término evoca un mosaico que se ensambla pieza por pieza a lo largo de los siglos, donde cada profeta añade fragmentos hasta que Cristo presenta el cuadro completo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4182', 'spa', 'multicolor, multiforme; que exhibe gran variedad o complejidad', 'Este vívido adjetivo compuesto combina ''muchos'' con ''variado'' para describir algo que despliega numerosos colores o formas. En Efesios 3:10, Pablo describe la sabiduría de Dios como ''multiforme'', caleidoscópica en su variedad y complejidad. El término se usaba para telas multicolores, diseños intrincados y patrones complejos. La sabiduría de Dios no es monocromática ni simple, sino que exhibe una variedad infinita, revelada a través de la diversa unidad de la iglesia ante los poderes cósmicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4183', 'spa', 'Muchos, mucho, gran; de número, cantidad, magnitud o grado; también comparativo ''mucho más'' y frecuentativo ''muchas veces''', 'Πολύς es el adjetivo griego por excelencia para expresar cantidad abundante, y su uso neotestamentario abarca casi toda clase de abundancia: muchas personas, mucho sufrimiento, grandes multitudes e intensa emoción. Con 361 apariciones, se cuenta entre los adjetivos más frecuentes del Nuevo Testamento. Su flexibilidad se manifiesta en cómo transita entre sustantivos contables (''muchos discípulos'', Mt 8:11) y sustantivos incontables o abstractos (''mucho fruto'', Jn 12:24; ''mucha confianza'', Flm 1:8). Las formas comparativas generan un patrón retórico distintivo en las cartas paulinas: ''¡cuánto más...!'' (Ro 5:9, 10, 15, 17), construyendo argumentos de menor a mayor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4184', 'spa', 'muy compasivo, profundamente misericordioso; que posee gran ternura y misericordia', 'Este adjetivo compuesto intensifica el concepto de compasión, significando literalmente ''de muchas entrañas'', ya que los antiguos ubicaban las emociones en los órganos internos. En Santiago 5:11, describe al Señor como ''muy compasivo'', enfatizando la profundidad y abundancia de su misericordia. El término va más allá de la bondad ordinaria para expresar una compasión profunda y visceral, la que conmueve lo más íntimo del ser. La misericordia de Dios no es medida ni calculada, sino desbordante y abundante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4185', 'spa', 'Muy costoso, caro, precioso; de gran valor o que requiere un gasto considerable', 'Este adjetivo describe lo que es muy costoso o de gran precio, aplicado frecuentemente a objetos preciosos de valor excepcional. Una mujer unge a Jesús con ungüento «muy costoso» de un frasco de alabastro (Marcos 14:3). Pablo advierte contra los adornos costosos para las mujeres, enfatizando más bien la belleza imperecedera de un espíritu apacible (1 Timoteo 2:9). Pedro igualmente elogia lo «precioso» de un espíritu manso y tranquilo ante los ojos de Dios (1 Pedro 3:4). La palabra distingue entre el adorno externo y costoso y el valor incomparable del carácter interior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4186', 'spa', 'Muy precioso, de altísimo valor, sumamente costoso o atesorado', 'Similar al término anterior pero con mayor intensidad, este adjetivo significa de gran precio o muy precioso. Un mercader encuentra una perla de «gran valor» y vende todo para adquirirla (Mateo 13:46). María unge los pies de Jesús con ungüento de nardo «muy precioso» (Juan 12:3). Pedro dice a los creyentes que su fe probada es «más preciosa» que el oro perecedero (1 Pedro 1:7). La palabra apunta de manera constante al valor supremo, ya sea una perla perfecta, una fragancia extravagante o una fe refinada que resiste el fuego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4187', 'spa', 'de muchas maneras, de diversas formas; a través de múltiples métodos o modos', 'Este adverbio describe variedad en la manera o el método, significando literalmente ''de muchos giros'' o ''de muchas formas''. En Hebreos 1:1, se empareja con ''en muchas partes'' para caracterizar la comunicación veterotestamentaria de Dios, que fue no solo fragmentaria sino también entregada por medios diversos: visiones, sueños, voz audible, señales y actos proféticos. La riqueza de la experiencia profética contrasta con la revelación singular y unificada en Cristo, quien es la Palabra suprema.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4189', 'spa', 'Maldad, perversidad, malicia; depravación moral como disposición interior o en sus manifestaciones externas.', 'Sustantivo que abarca todo el espectro del mal moral, desde la intención maliciosa interior hasta las acciones perversas externas. Jesús denuncia la πονηρία de los fariseos cuando lo ponen a prueba con preguntas insinceras (Mateo 22:18) y cuando su piedad exterior enmascara una «maldad y avaricia» interiores (Lucas 11:39). En Marcos 7:22 aparece en un catálogo de vicios que brotan del corazón humano, mientras que Pablo la incluye entre los frutos de la injusticia (Romanos 1:29). La forma plural en Efesios 6:12 — «fuerzas espirituales de maldad» — la extiende al ámbito cósmico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4190', 'spa', 'Malo, malvado, perverso; sustantivado como ''el Maligno'' (Satanás) o ''el mal'' como concepto abstracto; raramente, dañino físicamente.', 'Uno de los adjetivos principales del Nuevo Testamento para el mal moral, πονηρός describe personas, acciones, pensamientos y realidades espirituales como malos, perversos o nocivos. Su uso teológico más distintivo es el sustantivado ὁ πονηρός, ''el Maligno'', referido a Satanás como agente personal de corrupción (Mat 13:19, 38; 1 Jn 5:19). La petición del Padrenuestro, ''líbranos del mal'' (Mat 6:13), es célebremente ambigua entre el mal abstracto y el Maligno como ser personal. El español distingue malo (cualidad moral) de maligno (el Enemigo personal), mientras que el alemán böse cubre ambos sentidos, reflejando la ambigüedad griega. Un solo pasaje de Apocalipsis (16:2) conserva el sentido clásico físico de ''doloroso, penoso''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4191', 'spa', 'penoso, doloroso; en mal estado, inútil; moralmente malo, malvado; dañino', 'El adjetivo πονηρός abarca desde el esfuerzo físico («agobiado por los trabajos», como Heracles descrito como «el más laborioso y mejor») hasta la condición deplorable («aliados inútiles», «un caballo inservible») y la maldad moral. Obras penosas, alimentos dañinos y un mal comienzo emplean πονηρός. La expresión πονηρῶς ἔχειν significa «estar en mala situación». Desde la fatiga física, el término se desliza hacia la inutilidad y luego hacia la perversidad activa. El uso neotestamentario enfatiza el sentido moral: el maligno, las obras malas, el corazón perverso. El recorrido semántico de «agotado por el trabajo» a «malvado» refleja la vinculación griega entre sufrimiento, disfunción y vicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4192', 'spa', 'Dolor, angustia, fatiga; trabajo arduo o sufrimiento que desgasta profundamente.', 'Sustantivo que en el griego clásico significaba trabajo físico arduo o el esfuerzo de la batalla, pero que en el NT se desplazó hacia la angustia y el dolor. En Apocalipsis describe el dolor del juicio divino (Ap 16:10-11) y la aflicción que dejará de existir en la nueva creación (Ap 21:4). Colosenses 4:13 lo emplea para el esfuerzo laborioso de Epafras en favor de las iglesias. La palabra conlleva el peso de algo que cuesta mucho, ya sea sufrimiento corporal o esfuerzo extenuante en bien de otros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4193', 'spa', 'Ποντικός (Pontikós); gentilicio que designa a una persona originaria del Ponto, región costera del Mar Negro en Asia Menor', 'Este adjetivo étnico identifica a alguien procedente del Ponto, una región situada a lo largo de la costa sur del Mar Negro en el norte de Asia Menor. En Acts 18:2, se describe a Aquila como «póntico» o «del Ponto», proporcionando el trasfondo geográfico de este matrimonio de fabricantes de tiendas que se convirtieron en colaboradores del ministerio de Pablo. El Ponto era conocido por su agricultura y comercio, y contaba con una población judía considerable. Conocer el origen de Aquila ayuda a explicar su presencia en Roma y posteriormente en Corinto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4194', 'spa', 'Poncio; nombre romano, famosamente llevado por Poncio Pilato, prefecto de Judea', 'Este nombre latino aparece en el Nuevo Testamento exclusivamente en referencia a Poncio Pilato, el prefecto romano que presidió el juicio y la crucifixión de Jesús. El Evangelio de Lucas lo introduce con precisa ubicación histórica como gobernador de Judea durante el año decimoquinto de Tiberio César (Lucas 3:1). El nombre figura en la fórmula confesional cristiana primitiva conservada en 1 Timoteo 6:13, donde la «buena confesión» de Jesús ante Poncio Pilato se convierte en un punto fijo de referencia histórica. Hechos 4:27 lo incluye entre quienes se reunieron contra el ungido de Dios. En griego clásico πόντιος se asocia con «del mar», pero en el Nuevo Testamento funciona exclusivamente como nombre propio romano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4198', 'spa', 'Ir, marchar, viajar; en sentido figurado: caminar o conducirse en un modo de vida', 'El verbo griego estándar para el movimiento intencional de un lugar a otro, πορεύομαι aparece a lo largo del Nuevo Testamento en mandatos, narraciones y metáforas teológicas por igual. Jesús envía a los magos con ''id (πορευθέντες) e investigad con diligencia al niño'' (Mt 2:8), y la Gran Comisión descansa sobre el mismo participio: ''id (πορευθέντες) y haced discípulos'' (Mt 28:19). Más allá del viaje literal, la palabra porta una rica carga figurada heredada del uso septuagintal, describiendo cómo uno ''camina'' por la vida: Zacarías e Isabel ''andando (πορευόμενοι) en todos los mandamientos del Señor'' (Lc 1:6). En Hechos, la experiencia de Pablo en el camino a Damasco se enmarca con este verbo tres veces (Hch 9:3; 22:6; 26:13), convirtiendo una ruta geográfica en un punto de inflexión teológico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4199', 'spa', 'Destruir, devastar o asolar por completo; usado frecuentemente para ataques violentos contra comunidades o instituciones', 'Este verbo describe destrucción violenta y devastación, particularmente de ciudades, instituciones o comunidades. En el griego clásico se empleaba para saqueos y estragos militares. El Nuevo Testamento lo usa específicamente para la persecución violenta que Saulo emprendió contra la iglesia primitiva antes de su conversión. Las traducciones al español, francés y alemán enfatizan de manera uniforme la fuerza destructiva, mientras que los participios ingleses captan tanto el aspecto continuo como el completado de la devastación que Pablo infligió a la comunidad creyente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4201', 'spa', 'Πόρκιος (Pórkios); Porcio, nombre de familia latino, como en Porcio Festo, gobernador romano de Judea', 'Se trata de la transliteración del nombre latino Porcius (Porcio), el nombre de familia (nomen) de Porcio Festo, el gobernador romano que sucedió a Félix en Judea. En Acts 24:27, la referencia identifica al nuevo procurador que heredó el caso de Pablo. Las convenciones romanas de nomenclatura empleaban tres nombres; Porcius era el nombre familiar que indicaba pertenencia al clan. El mandato de Festo (aprox. 59-62 d.C.) fue testigo de la apelación de Pablo al César y su posterior viaje a Roma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4202', 'spa', 'Inmoralidad sexual, fornicación; toda conducta sexual ilícita fuera del pacto matrimonial, usada también figuradamente para la idolatría', 'Inmoralidad sexual, fornicación; toda conducta sexual ilícita fuera del pacto matrimonial, usada también figuradamente para la idolatría');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4203', 'spa', 'Cometer inmoralidad sexual o fornicación; practicar conducta sexual ilícita; también usado metafóricamente para la infidelidad espiritual.', 'Πορνεύω, raíz de la que el español deriva «pornografía», significa practicar la inmoralidad sexual, abarcando fornicación, prostitución y unión sexual ilícita en sentido amplio. Pablo lo emplea como prohibición tajante: «Huid de la fornicación» (1 Co 6:18), y recuerda que 23.000 cayeron en un solo día cuando Israel cometió inmoralidad (1 Co 10:8). En Apocalipsis el verbo adquiere su dimensión metafórica veterotestamentaria, donde la inmoralidad sexual se convierte en figura de infidelidad idolátrica: Jezabel «enseña y seduce a mis siervos a fornicar» (Ap 2:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4204', 'spa', 'πόρνη — prostituta, ramera; usado literalmente y figuradamente para la idolatría espiritual en Apocalipsis. El sustantivo πόρνη (''prostituta, ramera'')', 'πόρνη — prostituta, ramera; usado literalmente y figuradamente para la idolatría espiritual en Apocalipsis. El sustantivo πόρνη (''prostituta, ramera'') designa a una mujer que se dedica a la actividad sexual a cambio de pago. En el Nuevo Testamento opera en dos registros. Literalmente, aparece en la sorprendente declaración de Jesús de que ''los publicanos y las rameras van delante de vosotros al reino de Dios'' (Mt 21:31-32) y en la advertencia de Pablo contra la unión con prostitutas (1 Co 6:15-16). La epístola a los Hebreos recuerda a Rahab la ramera como modelo de fe (He 11:31; cf. Stg 2:25). Figuradamente, el Apocalipsis la emplea como ''la gran ramera'' (Ap 17:1, 5, 15-16; 19:2), símbolo del poder imperial idolátrico que seduce a las naciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4205', 'spa', 'Persona sexualmente inmoral, alguien que practica la fornicación o la transgresión sexual. El sustantivo πόρνος designa a una persona que se entrega a', 'Persona sexualmente inmoral, alguien que practica la fornicación o la transgresión sexual. El sustantivo πόρνος designa a una persona que se entrega a la inmoralidad sexual; aparece en listas de vicios y advertencias de exclusión a lo largo de las epístolas y Apocalipsis. Pablo instruye a los creyentes corintios a no asociarse con nadie que, llamándose hermano, sea un πόρνος (1 Co 5:9–11), y declara que tales personas no heredarán el reino de Dios (1 Co 6:9). Efesios 5:5 equipara al sexualmente inmoral con un idólatra, y Hebreos 12:16 invoca a Esaú como modelo del πόρνος profano. Apocalipsis sitúa al πόρνος fuera de la ciudad santa (Ap 21:8; 22:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4206', 'spa', 'Lejos, a distancia; usado para indicar lejanía espacial o figurada.', 'Adverbio que indica distancia o lejanía, ya sea literal o metafórica. Jesús cita dos veces la reprensión de Isaías: «Este pueblo me honra con los labios, pero su corazón está lejos de mí» (Mt 15:8; Mc 7:6), empleando πόρρω para expresar distancia espiritual. Lucas lo usa espacialmente: un rey que envía una embajada estando aún «lejos» el enemigo (Lc 14:32) y Jesús que aparenta ir «más lejos» en el camino de Emaús (Lc 24:28). El vocablo tiende un puente entre la distancia física y la relacional con igual naturalidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4208', 'spa', 'más lejos, más adelante, hacia adelante; adverbio de dirección que indica movimiento o posición adelante en espacio o tiempo', 'Este adverbio significa «más lejos» o «hacia adelante» y aparece en diversos dialectos griegos con formas como πρόσω, πρόσσω, πόρσω y πόρρω. Indica principalmente movimiento espacial hacia adelante o en progresión, como al conducir ejércitos al frente o impulsar caballos adelante. La palabra también posee extensiones temporales, refiriéndose a lo que está más adelante en el tiempo. Los autores clásicos la empleaban con verbos de movimiento para enfatizar el avance o la progresión hacia una meta o destino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4209', 'spa', 'Tela o vestidura de púrpura; el costoso tinte o tejido asociado con la realeza y la riqueza.', 'Se refiere al costoso tejido teñido de púrpura, extraído del caracol marino múrice, un artículo de lujo en todo el Mediterráneo antiguo. En el relato de la pasión de Marcos, los soldados visten a Jesús con púrpura como manto real burlesco (Mr 15:17, 20). En la parábola del hombre rico, el contraste de Lázaro se viste de púrpura a diario (Lc 16:19). Apocalipsis incluye la púrpura entre las mercancías extravagantes de Babilonia (Ap 18:12). Cada aparición vincula este tejido con demostraciones de poder, riqueza o su subversión irónica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4210', 'spa', 'Purpúreo, de color púrpura; que describe vestiduras o telas teñidas con el costoso tinte púrpura.', 'Forma adjetiva correspondiente al sustantivo πορφύρα, que describe algo teñido o coloreado de púrpura. En el relato de la pasión según Juan, los soldados colocan un manto purpúreo sobre Jesús (Jn 19:2, 5), en paralelo con el uso del sustantivo en Marcos. Apocalipsis lo emplea para describir la vestimenta de la gran ramera (Ap 17:4) y el lujoso adorno de Babilonia (Ap 18:16). Como adjetivo, modifica vestiduras y textiles, evocando siempre esplendor imperial o extravagante, ya sea genuinamente regio o grotescamente parodiado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4211', 'spa', 'Vendedora de púrpura; comerciante de telas o tintes purpúreos, artículo de lujo en el mundo antiguo', 'Este término ocupacional identifica a una persona que comercia con telas teñidas de púrpura o con el tinte mismo, un producto de lujo en el mundo antiguo. En Acts 16:14, Lidia es identificada como «vendedora de púrpura» procedente de Tiatira, ciudad famosa por su industria de teñido púrpura. El tinte de púrpura era extraordinariamente costoso, ya que se extraía de caracoles marinos, lo que lo convertía en símbolo de estatus para los adinerados. La ocupación de Lidia sugiere tanto perspicacia comercial como probable prosperidad, lo cual explica su capacidad para hospedar al equipo de Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4212', 'spa', '¿Cuántas veces? (adverbio interrogativo de frecuencia)', 'Adverbio interrogativo que pregunta por la frecuencia o el número de veces que algo ocurre. En griego clásico funcionaba tanto como palabra interrogativa como de manera indefinida con el sentido de «tantas veces». El Nuevo Testamento lo emplea exclusivamente en la enseñanza de Jesús, apareciendo en dos pasajes paralelos sobre Jerusalén y una vez en la pregunta de Pedro sobre el perdón. Las tres instancias involucran a Jesús abordando cuestiones de acción repetida y paciencia divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4213', 'spa', 'bebida; el acto de beber o la bebida misma', 'Este sustantivo designa tanto el acto de beber como la bebida en sí. En el griego clásico podía referirse al consumo de líquidos en general o específicamente a banquetes y festividades. En el Nuevo Testamento su uso es más sobrio, apareciendo en contextos que contrastan el sustento físico con el espiritual o que enumeran prácticas corporales sujetas a regulación religiosa. Pablo lo emplea para relativizar el consumo físico frente a las realidades espirituales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4214', 'spa', '¿Cuánto? ¿Cuántos? Interrogativo de cantidad, grado o número, frecuente en comparaciones retóricas', '¿Cuánto? ¿Cuántos? Interrogativo de cantidad, grado o número, frecuente en comparaciones retóricas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4215', 'spa', 'Río o corriente de agua; se usa literalmente para cursos de agua geográficos y figuradamente en imágenes proféticas. En el griego clásico, ποταμός pod', 'Río o corriente de agua; se usa literalmente para cursos de agua geográficos y figuradamente en imágenes proféticas. En el griego clásico, ποταμός podía designar desde un pequeño arroyo hasta un gran río o incluso un canal artificial. En el Nuevo Testamento aparece tanto en registro literal como simbólico. Juan el Bautista sumerge a los conversos en el río Jordán (Mt 3:6; Mr 1:5), la parábola de Jesús advierte sobre inundaciones que golpean una casa (Mt 7:25, 27), y Apocalipsis describe un río del agua de vida que fluye del trono de Dios (Ap 22:1-2). El francés fleuve distingue un gran río que desemboca en el mar, mientras que el alemán usa tanto Fluss como Strom, reflejando el rango de la palabra desde un curso de agua ordinario hasta un torrente abrumador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4216', 'spa', 'Arrastrado por el río; llevado por una inundación o torrente, arrebatado por la corriente de agua', 'Este adjetivo compuesto describe el ser arrastrado o llevado por un río o una inundación. En Revelation 12:15, el dragón intenta hacer que la mujer sea «arrastrada por el río», es decir, arrebatada por una inundación que sale de su boca. La vívida imagen transmite una fuerza abrumadora y el peligro de ser arrastrado hacia la destrucción. Las audiencias antiguas, familiarizadas con crecidas repentinas y corrientes fluviales, comprenderían de inmediato el peligro mortal. Milagrosamente, la tierra ayuda a la mujer tragándose la inundación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4217', 'spa', '¿De qué clase? ¿Qué tipo de? Adjetivo interrogativo que expresa asombro o indagación sobre la naturaleza de algo.', 'Adjetivo-pronombre interrogativo que pregunta por la cualidad o el carácter de algo, frecuentemente teñido de asombro. Los discípulos exclaman: «¿Qué clase de hombre es este, que hasta los vientos y el mar le obedecen?» (Mt 8:27). De igual modo, un espectador se pregunta «qué clase de mujer» está tocando a Jesús (Lc 7:39), y los discípulos se maravillan ante «¡qué piedras y qué edificios!» del templo (Mr 13:1). La palabra no transmite una pregunta neutra, sino un cuestionamiento admirado o evaluativo sobre la naturaleza de lo observado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4218', 'spa', 'En otro tiempo, antes (marcando un estado pasado); alguna vez, jamás (con negación o preguntas); por fin, al cabo.', 'En otro tiempo, antes (marcando un estado pasado); alguna vez, jamás (con negación o preguntas); por fin, al cabo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4219', 'spa', '¿Cuándo? (adverbio temporal interrogativo); alguna vez, jamás (en cláusulas de temor con μή); acaso, quizás (raro).', '¿Cuándo? (adverbio temporal interrogativo); alguna vez, jamás (en cláusulas de temor con μή); acaso, quizás (raro).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4220', 'spa', 'Si, acaso (entre dos alternativas); cuál de las dos opciones; partícula interrogativa disyuntiva', 'Esta partícula interrogativa introduce una pregunta que involucra dos alternativas, preguntando «cuál de las dos» o «si... o». En John 7:17, Jesús dice que quien esté dispuesto a hacer la voluntad de Dios conocerá si la enseñanza proviene de Dios o si Jesús habla por cuenta propia. La partícula enmarca una elección binaria que requiere discernimiento. La gramática señala que hacer la voluntad de Dios proporciona el criterio para evaluar la fuente de la enseñanza de Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4221', 'spa', 'Copa — un recipiente para beber; literalmente de vajilla, figuradamente de la porción de sufrimiento o bendición asignada por Dios.', 'Copa — un recipiente para beber; literalmente de vajilla, figuradamente de la porción de sufrimiento o bendición asignada por Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4222', 'spa', 'Dar de beber a alguien; por extensión, regar o irrigar plantas y campos. Un verbo que abarca todo el espectro desde ofrecer un vaso de agua hasta rega', 'Dar de beber a alguien; por extensión, regar o irrigar plantas y campos. Un verbo que abarca todo el espectro desde ofrecer un vaso de agua hasta regar un huerto. En los Evangelios, Jesús eleva el simple acto de dar de beber a un sediento a prueba de discipulado (Mt 10:42; 25:35). Pablo extiende luego la imagen al ámbito agrícola en 1 Corintios 3:6-8, donde él ''plantó'' y Apolos ''regó''. La metáfora transita sin esfuerzo de la hospitalidad al sustento espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4223', 'spa', 'Ποτίολοι; Puteoli (actual Pozzuoli), ciudad portuaria cerca de Nápoles en la costa italiana', 'Este es el nombre griego de Puteoli, el principal puerto italiano en la bahía de Nápoles donde solían atracar los barcos procedentes del Mediterráneo oriental. En Hechos 28:13, el barco de Pablo llega a Puteoli tras su azaroso viaje hacia Roma. La ciudad funcionaba como puerto principal de Roma para los navíos de grano procedentes de Egipto y como centro de comercio oriental. El hallazgo de creyentes allí (28:14) da testimonio de la temprana expansión del evangelio hasta los centros comerciales estratégicos del mundo antiguo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4224', 'spa', 'fiestas de bebida, banquetes centrados en el consumo excesivo de vino; orgías alcohólicas', 'Este término designa reuniones sociales centradas en la bebida, generalmente vino, a menudo consumido en exceso. En 1 Pedro 4:3 aparece en un catálogo de vicios gentiles que los creyentes han dejado atrás. No se trataba de ocasiones sociales moderadas, sino de eventos caracterizados por la embriaguez y las conductas que la acompañan. Aunque los simposios antiguos podían ser reuniones literarias refinadas, el término aquí sugiere exceso y desenfreno moral, parte del estilo de vida pagano incompatible con la santidad cristiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4225', 'spa', 'En algún lugar, en alguna parte; también «dónde» (interrogativo) y «aproximadamente» (con números).', 'Este discreto adverbio enclítico πού cumple funciones variadas pero importantes. Puede significar «en algún lugar» de manera vaga e indefinida: los marineros en Hch 27:29 presentían que se acercaban «a alguna tierra», y Hebreos cita las Escrituras con un casual «alguien testificó en algún lugar» (Heb 2:6; 4:4). También funciona como interrogativo «dónde» (Mr 15:47; Jn 1:39). En Ro 4:19 adquiere el sentido aproximativo de «como» cien años. Cada uso refleja un matiz diferente de imprecisión o indagación espacial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4226', 'spa', 'Adverbio interrogativo que significa ''¿dónde?'' — usado para preguntar por ubicación, destino o, raramente, un lugar indefinido.', 'Adverbio interrogativo que significa ''¿dónde?'' — usado para preguntar por ubicación, destino o, raramente, un lugar indefinido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4227', 'spa', 'Πούδης; Pudente, nombre personal latino de un creyente en Roma', 'Este es la forma griega del nombre latino Pudens, que identifica a un creyente en Roma que envía saludos a Timoteo. En 2 Timoteo 4:21 aparece entre varios cristianos romanos que mantienen contacto con Pablo durante su encarcelamiento final. El nombre Pudens era común en la sociedad romana y significaba ''modesto'' o ''pudoroso''. Aunque sabemos poco más de este individuo, su mención en la última carta de Pablo testifica de las redes de comunión que unían a las primeras comunidades cristianas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4228', 'spa', 'Pie: la extremidad inferior del cuerpo, usado frecuentemente en contextos de sumisión, autoridad, purificación ritual y peregrinaje.', 'πούς aparece 93 veces en el Nuevo Testamento y, aunque siempre designa el pie físico, los contextos en que aparecen los pies son extraordinariamente variados y culturalmente significativos. Los pies se lavan como acto de servicio humilde (Jn 13:5-14), se ungen en devoción (Lc 7:38, 46), y se sacuden del polvo como juicio profético (Mat 10:14; Hch 13:51). La gente cae a los pies de Jesús en adoración o súplica (Mc 5:22; Ap 1:17). La expresión ''bajo los pies'' señala sujeción total, derivada del Salmo 110:1 y aplicada al señorío cósmico de Cristo (1 Co 15:25-27; Ef 1:22). El español pies, el francés pied y el alemán Fuß comparten el sentido anatómico, pero requieren anotación cultural para transmitir la profundidad simbólica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4229', 'spa', 'Asunto, cosa, hecho — un acontecimiento concreto, caso legal, negocio o realidad abstracta bajo consideración. El sustantivo πρᾶγμα (pragma) abarca un', 'Asunto, cosa, hecho — un acontecimiento concreto, caso legal, negocio o realidad abstracta bajo consideración. El sustantivo πρᾶγμα (pragma) abarca un amplio rango semántico que va desde sucesos concretos hasta realidades abstractas. Lucas lo emplea para los acontecimientos ''cumplidos entre nosotros'' (Lc 1:1), y en Mateo 18:19 designa cualquier ''asunto'' sobre el cual dos creyentes concuerdan en oración. Hechos 5:4 lo usa para el hecho que Ananías concibió en su corazón. Pablo lo utiliza técnicamente para un caso legal o pleito (1 Co 6:1) y para un negocio o posible agravio (1 Ts 4:6). El autor de Hebreos lo eleva al registro filosófico: Dios confirmó su promesa mediante ''dos cosas inmutables'' (Heb 6:18), y la fe es la certeza de las ''cosas'' que se esperan (Heb 11:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4230', 'spa', 'asuntos, negocios; ocupaciones o preocupaciones mundanas; actividades civiles', 'Este término designa los asuntos prácticos, transacciones comerciales u ocupaciones mundanas que demandan atención y energía. En 2 Timoteo 2:4, Pablo advierte que el soldado no se enreda en los asuntos de la vida civil para poder agradar a quien lo alistó. La metáfora militar ilustra una devoción singular: los soldados eficaces evitan compromisos que distraigan de su misión principal. Para los ministros cristianos, el paralelo es claro: evitar los enredos mundanos que diluyen el enfoque espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4231', 'spa', 'negociar, comerciar, invertir; dedicarse a actividades comerciales para obtener ganancia', 'Este verbo significa ocuparse en negocios, comerciar o invertir, es decir, poner recursos a trabajar para obtener ganancias. En Lucas 19:13, el noble ordena a sus siervos ''negociad'' con las minas hasta su regreso. El término implica participación activa, no retención pasiva. Sugiere actividad emprendedora, tomar iniciativa y asumir riesgos para generar rendimientos. La parábola elogia la mayordomía fiel que multiplica los recursos del amo mediante una inversión diligente y sabia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4232', 'spa', 'El Pretorio: residencia oficial del gobernador romano, cuartel militar o, por extensión, la guardia pretoriana.', 'Préstamo directo del latín, πραιτώριον designa la sede oficial de la autoridad provincial romana. En los Evangelios se refiere al cuartel general de Pilato en Jerusalén, donde Jesús fue juzgado y escarnecido por los soldados (Mt 27:27; Jn 18:28, 33). Marcos 15:16 lo identifica con el patio interior (αὐλή). En Filipenses 1:13, Pablo emplea el término en sentido más amplio, refiriéndose probablemente a la guardia pretoriana o a la casa imperial en Roma. La forma española «Pretorio» conserva el préstamo latino prácticamente inalterado, lo que subraya el reconocimiento universal de esta institución romana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4234', 'spa', 'Hecho, acción o práctica; también función o papel dentro de un conjunto mayor (como en la metáfora del cuerpo en Rom 12:4).', 'En el Nuevo Testamento, πρᾶξις lleva el peso de la conducta moral: la suma de lo que una persona hace, para bien o para mal. Jesús declara que a cada uno se le retribuirá conforme a sus obras (Mt 16:27), y Pablo insta a los creyentes a hacer morir las prácticas pecaminosas del cuerpo (Rom 8:13). No obstante, la palabra posee también un sentido más discreto: en Rom 12:4, Pablo la emplea para describir la función particular que cada miembro cumple dentro del cuerpo de Cristo, de manera semejante a como la vida cívica griega usaba πρᾶξις para el oficio o la tarea asignada a cada persona.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4235', 'spa', 'manso, apacible, gentil; que describe un temperamento o disposición calmada y no agresiva en personas o cosas', 'Este adjetivo, que aparece como πρᾶος en la prosa ática y πρᾱΰς en la poesía épica, describe a alguien manso, apacible o gentil de temperamento. Los escritores griegos antiguos lo contrastaban con la dureza, la ira o la fiereza, convirtiéndolo en una virtud tanto en la ética clásica como en el uso bíblico. El Nuevo Testamento conserva este sentido al describir los rasgos de carácter bienaventurados. En la Septuaginta y los escritos cristianos, adquirió un significado moral profundo como cualidad de moderación humilde y resistencia paciente, no debilidad ni pasividad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4236', 'spa', 'mansedumbre, gentileza, apacibilidad; la cualidad de ser manso o apacible en temperamento y acción', 'Este sustantivo denota la cualidad de la mansedumbre o la apacibilidad, oponiéndose directamente a la dureza, la ira o la ferocidad en la literatura griega clásica. Filósofos como Aristóteles lo discutieron como una virtud equilibrada frente al temperamento irascible. La palabra evolucionó en el griego helenístico y aparece tanto en la Septuaginta como en el Nuevo Testamento como πραΰτης, donde adquirió un significado ético más profundo. Los autores bíblicos la usaron para describir un espíritu de humilde sumisión a Dios y tolerancia paciente hacia los demás: no debilidad, sino fortaleza bajo control.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4238', 'spa', 'Hacer, practicar o llevar a cabo; dedicarse habitualmente a algo; cobrar o recaudar pagos; en voz pasiva, ser hecho.', 'Hacer, practicar o llevar a cabo; dedicarse habitualmente a algo; cobrar o recaudar pagos; en voz pasiva, ser hecho.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4239', 'spa', 'Manso, apacible, humilde de carácter; quien ejerce el poder con moderación en lugar de agresividad.', 'Describe una cualidad de fortaleza apacible: no debilidad, sino poder bajo control. Jesús se lo aplica a sí mismo («soy manso y humilde de corazón», Mt 11:29) y aparece en la promesa de las Bienaventuranzas de que los mansos heredarán la tierra (Mt 5:5). La cita de Zacarías en Mateo 21:5 presenta al rey mesiánico como πραΰς, montado humildemente sobre un asno. Pedro elogia un «espíritu apacible y tranquilo» como precioso ante Dios (1 P 3:4). El término asocia constantemente la mansedumbre con la autoridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4240', 'spa', 'πραΰτης — mansedumbre, dulzura; la cualidad de autodominio humilde y apacible como virtud espiritual. El sustantivo πραΰτης (anteriormente πραότης) de', 'πραΰτης — mansedumbre, dulzura; la cualidad de autodominio humilde y apacible como virtud espiritual. El sustantivo πραΰτης (anteriormente πραότης) denota mansedumbre, dulzura y apacibilidad de carácter — no debilidad, sino fuerza contenida. En el griego clásico describía el temperamento sereno opuesto a la aspereza (ἀγριότης) y la ira pronta (ὀργιλότης). Pablo la incluye entre el fruto del Espíritu (Gá 5:23) e insta a ella como la postura adecuada para restaurar a un hermano caído (Gá 6:1), apelando a los corintios ''por la mansedumbre y la ternura de Cristo'' (2 Co 10:1). Aparece junto a la humildad y la paciencia en Ef 4:2 y Col 3:12, conformando el perfil del carácter del creyente maduro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4241', 'spa', 'Convenir, ser apropiado o decoroso; expresa propiedad moral o situacional y lo que es digno o correspondiente.', 'Verbo impersonal que expresa que algo es conveniente, apropiado o decoroso — una palabra discreta pero poderosa para la propiedad moral y teológica. Jesús la emplea en su bautismo: «conviene que cumplamos toda justicia» (Mt 3:15), estableciendo un principio de correspondencia divina. Pablo la aplica al decoro en el culto (1 Co 11:13), a la conducta ética (Ef 5:3) y a las cualidades esperadas de los líderes cristianos (Tit 2:1). Tanto el español «convenir» como el francés «convenir» derivan del latín convenire, reflejando la idea de que las cosas «encajan» adecuadamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4244', 'spa', 'consejo de ancianos, presbiterio; cuerpo colectivo de líderes ancianos', 'Este término designa el consejo o cuerpo colectivo de ancianos en contextos judíos o cristianos. En el griego clásico se refería a un consejo de ancianos con autoridad de gobierno. El Nuevo Testamento conserva este sentido institucional, aludiendo tanto al consejo gobernante judío como a la asamblea cristiana de ancianos. La evidencia interlingüística muestra una traducción consistente como consejo o cuerpo colectivo, no como ancianos individuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4245', 'spa', 'Anciano; líder comunitario, antepasado o persona mayor, abarcando autoridad oficial, honor ancestral y edad comparativa.', 'En el mundo del Nuevo Testamento, esta palabra enlaza la autoridad institucional con la simple antigüedad. Con mayor frecuencia designa un dirigente oficial: un miembro del Sanedrín, un dirigente de la sinagoga o un supervisor de la iglesia, como se observa en los Evangelios y Hechos, donde ''los ancianos'' aparecen junto a los principales sacerdotes como guardianes institucionales. Sin embargo, la misma palabra puede remontarse en el tiempo para honrar a los fieles antepasados de Hebreos 11, o simplemente describir a alguien de mayor edad, como cuando el hijo mayor en la parábola del hijo pródigo se niega a celebrar (Lc 15:25). El español ancianos y el alemán Älteste captan esta doble dimensión de edad y autoridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4246', 'spa', 'anciano, hombre de edad avanzada; varón entrado en años', 'Este sustantivo se refiere a un hombre anciano, alguien de edad avanzada. A diferencia del término relacionado que designa un consejo de ancianos, esta palabra se centra en el individuo y no en la institución. Aparece en contextos que abordan la dignidad, el estatus o la autoidentificación de los hombres mayores. Pablo lo emplea tanto para describir a otros como posiblemente a sí mismo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4247', 'spa', 'mujeres ancianas, mujeres de edad avanzada; mujeres mayores con madurez y experiencia', 'Este término femenino designa a las mujeres de edad avanzada, sugiriendo no solo años vividos sino también la sabiduría y madurez que deberían acompañarlos. En Titus 2:3, Pablo instruye que las ancianas deben ser reverentes en su conducta y enseñar lo bueno, sirviendo como mentoras de las más jóvenes. El término no se refiere únicamente a la edad cronológica, sino a la madurez espiritual y la experiencia de vida que capacita a estas mujeres para ser modelos de piedad y guías en la vida cristiana práctica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4248', 'spa', 'de cabeza, boca abajo; caer hacia adelante o de bruces', 'Este adjetivo describe una posición o caída con el rostro hacia abajo, de cabeza o de bruces, lo opuesto a caer de espaldas. En Acts 1:18 describe cómo cayó Judas tras su suicidio, aunque los detalles exactos del suceso son debatidos textualmente. El término enfatiza la orientación descendente y hacia adelante de la caída. En contextos antiguos médicos y atléticos se usaba para describir posiciones corporales, pero aquí contribuye a los sombríos detalles del violento final de Judas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4249', 'spa', 'aserrar, cortar con sierra; partir en dos con sierra', 'Este verbo significa aserrar o cortar con sierra, refiriéndose específicamente al horrible método de ejecución o tortura. En Hebrews 11:37 aparece en un catálogo de sufrimientos soportados por testigos fieles: fueron aserrados por la mitad. La tradición asocia esta muerte con el profeta Isaías bajo el rey Manasés, aunque el versículo probablemente abarca a múltiples mártires. La naturaleza gráfica del término subraya la persecución extrema que los creyentes fieles a veces enfrentaron.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4250', 'spa', 'Antes, antes de — adverbio y conjunción temporal que indica que un evento precede a otro en el tiempo. πρίν funciona como adverbio y conjunción en el ', 'Antes, antes de — adverbio y conjunción temporal que indica que un evento precede a otro en el tiempo. πρίν funciona como adverbio y conjunción en el Nuevo Testamento, expresando consistentemente prioridad temporal — ''antes de que esto suceda'' o ''antes de que hagas aquello.'' Sus 13 ocurrencias se agrupan en torno a momentos narrativos decisivos, especialmente en la predicción de Jesús de que Pedro le negaría ''antes de que el gallo cante'' (Mt 26:34; Mr 14:30). La palabra también marca los tiempos divinos, como en Mt 1:18, donde María fue hallada encinta ''antes'' de que ella y José se unieran. La evidencia multilingüe confirma uniformemente un único sentido de precedencia temporal sin ramificación semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4251', 'spa', 'Prisca (forma completa de Priscila); esposa de Aquila, colaboradora de Pablo', 'Prisca es el nombre latino formal de la mujer también llamada Priscila, esposa de Aquila y destacada colaboradora en el ministerio de Pablo. Ella y su esposo eran fabricantes de tiendas que hospedaban iglesias en su hogar e instruyeron a Apolos en la fe. El nombre aparece en su forma completa «Prisca» en las cartas de Pablo, reflejando respeto y afecto. Esta mujer capaz siempre se menciona en contextos ministeriales, a menudo nombrada antes que su esposo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4252', 'spa', 'Priscila (diminutivo de Prisca); esposa de Aquila, colaboradora de Pablo', 'Priscila es la forma diminutiva o afectuosa de Prisca, usada por Lucas en Hechos para referirse a la misma mujer extraordinaria que colaboró con su esposo Aquila en el ministerio. La variación de formas (Prisca en las cartas de Pablo, Priscila en Hechos) refleja convenciones latinas comunes donde se empleaban tanto la forma formal como la familiar. Aparece como fabricante de tiendas, plantadora de iglesias, anfitriona e instructora teológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4253', 'spa', 'πρό — antes; preposición de prioridad temporal, posición espacial delante, o superioridad en rango.', 'πρό — antes; preposición de prioridad temporal, posición espacial delante, o superioridad en rango.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4254', 'spa', 'Ir delante o guiar el camino; también llevar a alguien adelante, o preceder en el tiempo. προάγω combina πρό (''antes'') con ἄγω (''conducir''), producien', 'Ir delante o guiar el camino; también llevar a alguien adelante, o preceder en el tiempo. προάγω combina πρό (''antes'') con ἄγω (''conducir''), produciendo un verbo que se mueve al frente -- espacial, causal o temporalmente. Su uso más vívido en el NT es la estrella que ''iba delante'' de los magos (Mt 2:9) y Jesús yendo delante de sus discípulos a Galilea (Mt 26:32; Mr 14:28). En Hechos adopta un giro transitivo: guardias llevan a Pedro, un carcelero saca a Pablo (Hch 12:6; 16:30). Las epístolas pastorales extienden la imagen al tiempo, hablando de profecías que ''precedieron'' acerca de Timoteo (1 Ti 1:18) y un mandamiento anterior que fue abrogado (He 7:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4255', 'spa', 'proponerse de antemano, resolver previamente; determinar o decidir con anticipación', 'Este verbo compuesto significa elegir o decidir de antemano, formar un propósito o resolución previa. En 2 Corinthians 9:7, Pablo instruye que cada uno dé según lo que haya propuesto en su corazón, una decisión deliberada y premeditada en lugar de impulsiva o forzada. El término enfatiza la intencionalidad y la determinación personal. La generosidad cristiana debe fluir de una convicción meditada, no de presión externa ni manipulación emocional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4256', 'spa', 'acusar previamente, hacer un cargo anterior; formular una acusación previa', 'Este verbo compuesto significa acusar o imputar de antemano, formular una alegación previa. En Romans 3:9, Pablo pregunta si los judíos tienen alguna ventaja y responde que ya ha acusado previamente que tanto judíos como griegos están todos bajo pecado. El ''de antemano'' se refiere a su argumentación previa en los capítulos 1-2, donde estableció la pecaminosidad universal del ser humano. El término enfatiza que esta acusación no es nueva, sino que ya fue demostrada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4257', 'spa', 'oír de antemano o previamente; recibir aviso o noticia anticipada', 'Este verbo compuesto significa oír de antemano o con anticipación, recibir una noticia o informe previo. En Colosenses 1:5, Pablo hace referencia a la esperanza guardada en los cielos, «de la cual ya habéis oído antes por la palabra de verdad del evangelio». Los colosenses habían recibido previamente este mensaje evangélico, y Pablo les recuerda ahora lo que ya saben. El elemento de anterioridad subraya la llegada previa del evangelio y el conocimiento que ya poseen, el cual debe anclarlos frente a las falsas enseñanzas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4259', 'spa', 'portal, vestíbulo, atrio exterior; área de entrada o pórtico', 'Este término diminutivo designa un área de entrada, vestíbulo o atrio exterior: el espacio que precede al patio o edificio principal. En Marcos 14:68, Pedro se retira al portal o atrio exterior tras la primera negación. La arquitectura antigua incluía estos espacios de transición entre la calle y los patios interiores. El desplazamiento de Pedro a este espacio intermedio refleja su posición ambigua: ya no está audazmente dentro con Jesús, pero tampoco completamente afuera en plena negación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4260', 'spa', 'Avanzar, ir adelante; progresar en edad o en desplazamiento físico, especialmente «avanzado en años».', 'Verbo que significa dar un paso adelante o avanzar, compuesto de πρό (adelante) + βαίνω (ir). En el NT aparece en dos contextos distintos. En Mateo 4:21 y Marcos 1:19, Jesús «sigue adelante» de un par de pescadores para encontrar a otro, un simple desplazamiento espacial. Pero en Lucas 1:7, 1:18 y 2:36, el verbo se combina con ἡμέρα (días) para formar la expresión idiomática «avanzados en días», que significa ancianos. El término refleja así una doble idea de progresión hacia adelante, tanto en el espacio como en el tiempo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4262', 'spa', 'relativo a las ovejas; específicamente, la Puerta de las Ovejas en Jerusalén', 'Este adjetivo significa «relativo a las ovejas», pero en el uso neotestamentario identifica específicamente la Puerta de las Ovejas en Jerusalén. En Juan 5:2, el estanque de Betesda se encuentra junto a esta puerta, por la cual se introducían las ovejas destinadas al sacrificio en el Templo. El nombre evoca el sistema sacrificial central en el culto judío. La precisión geográfica de Juan sitúa el ministerio de sanación de Jesús en la topografía de Jerusalén, mientras que el nombre de la puerta prefigura sutilmente su misión sacrificial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4263', 'spa', 'Oveja — animal ovino doméstico; en el NT, figura omnipresente del pueblo de Dios bajo cuidado pastoral.', 'Oveja — animal ovino doméstico; en el NT, figura omnipresente del pueblo de Dios bajo cuidado pastoral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4264', 'spa', 'incitar, instigar, impulsar; inducir a alguien a actuar', 'Este verbo significa empujar hacia adelante, instigar o incitar a alguien a actuar, a menudo con el matiz de impulsar desde detrás. En Mateo 14:8, la hija de Herodías, «instruida por su madre», pide la cabeza de Juan el Bautista. El término sugiere manipulación: la joven no originó esta petición, sino que fue inducida o instigada por su vengativa madre. El verbo capta la instigación entre bastidores que condujo a la ejecución de Juan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4265', 'spa', 'prever, proveer de antemano; hacer provisión anticipada para algo venidero', 'Este verbo abarca el doble sentido de mirar hacia adelante: tanto mentalmente (prever lo que sucederá) como prácticamente (hacer provisión para ello). En el uso clásico significaba prever acontecimientos o proveer contra necesidades futuras. La única aparición neotestamentaria (Hebreos 11:40) emplea la voz media en un contexto teológico: Dios, habiendo previsto algo mejor con respecto a nosotros, dispuso que los santos del Antiguo Testamento no alcanzaran la perfección sin la comunidad del nuevo pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4266', 'spa', 'suceder o existir previamente, haber sido hecho o cometido de antemano', 'Verbo compuesto que indica ocurrencia o existencia previa. El griego clásico lo empleaba de manera amplia para referirse a cosas que habían sucedido antes: eventos pasados, generaciones anteriores, guerras previas. Sin embargo, el uso de Pablo en Romanos 3:25 es forense y preciso: habla de pecados previamente cometidos antes de la obra expiatoria de Cristo. Las traducciones en múltiples idiomas subrayan la prioridad temporal: eran transgresiones que ya habían ocurrido antes de la cruz, las cuales Dios había pasado por alto en su paciencia hasta la revelación de su justicia en Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4267', 'spa', 'Conocer de antemano, prever; el conocimiento previo y la elección relacional de Dios sobre personas o eventos.', 'Verbo que significa conocer con anticipación, formado de πρό (antes) + γινώσκω (conocer). En el uso teológico, conlleva el peso del conocimiento previo divino: no mera predicción, sino un conocimiento relacional y electivo. Romanos 8:29 declara que a quienes Dios «conoció de antemano», también los predestinó, donde el conocer es personal e intencional. Romanos 11:2 afirma que Dios no ha rechazado al pueblo que «conoció de antemano». En 1 Pedro 1:20, Cristo mismo fue «conocido de antemano» antes de la fundación del mundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4270', 'spa', 'Escribir de antemano; exponer públicamente por escrito, designar o retratar abiertamente con anticipación.', 'Contiene dos sentidos interrelacionados que parten de la idea de escritura previa o pública. Pablo dice a los gálatas que Cristo crucificado fue «exhibido públicamente» ante sus ojos (Gal 3:1), evocando el sentido clásico de fijar un edicto público. En Romanos 15:4, lo que fue «escrito de antemano» sirve para nuestra instrucción. Efesios 3:3 alude a lo que Pablo «escribió antes» en la misma carta. Judas 1:4 describe a personas «señaladas desde antiguo» para juicio. El término siempre implica una inscripción previa y autoritativa que determina el presente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4271', 'spa', 'Evidente, manifiesto; claramente visible de antemano o a plena vista, imposible de ocultar', 'Este adjetivo describe aquello que es claramente visible, obvio o manifiesto, ya sea con anticipación o a plena vista. En el griego clásico enfatizaba tanto la previsión como lo conspicuo. El Nuevo Testamento lo emplea para describir pecados u obras buenas que ya resultan evidentes antes del juicio final. El término transmite una claridad tal que hace imposible cualquier ocultamiento, señalando realidades morales que se manifiestan por sí mismas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4272', 'spa', 'dar de antemano, dar primero o por adelantado, otorgar antes de recibir', 'Este verbo compuesto intensifica el sentido básico de ''dar'' mediante un prefijo que indica prioridad temporal. Su uso clásico abarcaba desde pagar por adelantado hasta dar antes que otros. La pregunta retórica de Pablo en Romanos 11:35 cita Job 41:11, desafiando cualquier noción de que el ser humano pudiera poner a Dios en deuda dándole primero. El verbo subraya la imposibilidad del mérito humano para establecer un reclamo sobre la gracia divina: Dios nunca es deudor, siempre es el dador original.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4273', 'spa', 'Traidor, delator; quien entrega o abandona a otro en momento de peligro', 'Este sustantivo designa a un traidor o delator: alguien que entrega a otra persona o la abandona en un momento de peligro. El griego clásico lo utilizaba para traidores políticos y quienes violaban juramentos. El Nuevo Testamento lo aplica tanto a Judas Iscariote en particular como al carácter general de los traidores. Conlleva una fuerte condenación moral, señalando una deslealtad profunda y deliberada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4274', 'spa', 'precursor, el que corre delante o va primero para preparar el camino', 'Originalmente usado para exploradores de caballería avanzada o naves rápidas enviadas delante de una flota, este término evocaba la imagen de alguien que abre camino para que otros lo sigan. El griego clásico lo aplicaba a jinetes que cabalgaban delante del ejército, a estrellas matutinas que anuncian el sol, e incluso a higos tempranos que aparecen antes de la cosecha principal. Hebreos 6:20 lo aplica a Jesús entrando al santuario celestial como nuestro precursor, el primero en entrar a favor de quienes le seguirán: un sacerdote pionero que abre acceso para todos los que vienen tras él.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4275', 'spa', 'prever, ver de antemano, anticipar; percibir lo venidero o tomar previsión para necesidades futuras', 'Este verbo en aoristo (cuyo presente es προοράω) significa ver de antemano o prever. En Homero podía referirse literalmente a divisar algo que estaba adelante, mientras que en el uso posterior desarrolló el sentido de prever acontecimientos futuros o tomar medidas cautelares. La voz media a menudo transmitía el matiz de velar por los propios intereses o hacer provisión para lo que se avecina. En contextos proféticos, podía aludir a una previsión inspirada divinamente o a la capacidad de anticipar las consecuencias antes de que se desplegaran.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4276', 'spa', 'esperar de antemano, ser el primero en esperar o haber puesto ya la esperanza', 'Verbo compuesto que combina la esperanza con prioridad temporal. El uso clásico significaba anticipar o esperar algo. En Efesios 1:12, Pablo probablemente se refiere a los creyentes judíos que habían esperado en el Mesías antes de que los gentiles fueran incluidos, o posiblemente a todos los que ya habían llegado a esperar en Cristo antes de que la carta fuera escrita. El tiempo perfecto enfatiza una esperanza ya establecida y continua. La expresión capta el privilegio de estar entre los primeros en reconocer y confiar en las promesas de Dios cumplidas en Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4277', 'spa', 'predecir, decir de antemano, declarar o proclamar anticipadamente', 'Esta forma aorista funcionaba donde προλέγω carecía de tiempo presente, significando hablar de antemano con énfasis en la declaración pública o el anuncio profético. El uso clásico incluía predecir eventos futuros y hacer proclamaciones públicas. En Hechos 1:16, Pedro se refiere a cómo la Escritura predijo la traición de Judas: el Espíritu Santo, por boca de David, habló de antemano sobre lo que habría de suceder. El verbo subraya la naturaleza profética de los textos veterotestamentarios que anticiparon los acontecimientos del ministerio de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G4280', 'spa', 'decir de antemano, predecir, anunciar con anticipación; declarar u ordenar públicamente por adelantado', 'Este verbo significa hablar de antemano o con anticipación, con dos aplicaciones principales en el griego clásico y bíblico. Primero, podía referirse a la predicción profética o la advertencia sobre sucesos futuros, como cuando oráculos o profetas anunciaban lo que vendría. Segundo, tenía el sentido administrativo de ordenar o prescribir algo públicamente por adelantado, como comandantes militares que disponían la reunión de tropas o funcionarios que proclamaban regulaciones. La voz pasiva solía indicar lo que había sido declarado o prescrito previamente. Los escritores del Nuevo Testamento lo emplearon para declaraciones proféticas cumplidas en Cristo.');